window.SOPHIA_BATCH_PAPERS=[{"id":"star-ptsd-psychosis","pmid":"42309103","year":"2026","journal":"The Lancet Psychiatry","topic":"创伤与精神病","type":"多中心务实随机试验","title":"同时面对创伤后应激和精神病症状，治疗能否两边兼顾？","paperTitle":"Trauma-focused therapy integrated with cognitive behavioural therapy for psychosis for people with post-traumatic stress disorder and psychosis (the STAR trial): a multicentre, pragmatic, randomised trial in the UK","desc":"英国 STAR 试验把创伤聚焦治疗整合进精神病认知行为治疗，比较“整合治疗加常规照护”和单独常规照护。305 名同时有 PTSD 与精神病的成人参与，研究观察 9 个月后的 PTSD 症状及其他临床结局。","caveat":"疗程长达 9 个月，治疗经过个别化；研究结论对应有专门训练团队的英国二级照护场景。","url":"https://pubmed.ncbi.nlm.nih.gov/42309103/","fullTextUrl":"https://eprints.whiterose.ac.uk/id/eprint/243172/1/1-s2.0-S2215036626000908-main.pdf"},{"id":"violence-nonspecialists","pmid":"42309105","year":"2026","journal":"The Lancet Psychiatry","topic":"创伤与暴力","type":"系统综述与荟萃分析","title":"经历战争或人际暴力后，非专科人员能提供哪些心理支持？","paperTitle":"Non-specialist delivered psychosocial care after war and interpersonal violence","desc":"这篇综述汇总 45 项随机试验、9,431 名暴力经历者，逐项比较抑郁、PTSD、焦虑与功能损害。全文显示四类结局的平均差异都偏向受训非专科人员提供的心理社会支持，但研究间差异和偏倚风险很高。","caveat":"研究跨越多种暴力类型、国家和干预，效果并不代表所有方案相同；作者也说明没有纳入具有亲历经验者参与研究。","url":"https://pubmed.ncbi.nlm.nih.gov/42309105/","fullTextUrl":"https://researchonline.lshtm.ac.uk/id/eprint/4682504/1/Patel-etal-2026-Non-specialist-delivered-psychosocial.pdf"},{"id":"prenatal-digital-mindfulness","pmid":"40324172","year":"2025","journal":"Journal of Medical Internet Research","topic":"孕产期与睡眠","type":"单盲随机对照试验","title":"手机正念课程能否帮孕妇缓解失眠？","paperTitle":"Effectiveness and Mechanisms of a Digital Mindfulness-Based Intervention for Subthreshold to Clinical Insomnia Symptoms in Pregnant Women: Randomized Controlled Trial","desc":"这项单盲随机试验纳入 160 名孕妇，测试六周微信数字正念课程加标准照护。全文报告孕期自评失眠平均差约 2 分，产后约 42 天时组间差异不再显著；同时记录了依从、失访与可能的作用机制。","caveat":"大多数结局由参与者在线自评，且项目效果没有延续到产后测量；不能据此推断长期效果。","url":"https://pubmed.ncbi.nlm.nih.gov/40324172/","fullTextUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12089866/"},{"id":"digital-behavioural-activation","pmid":"40526910","year":"2025","journal":"Journal of Medical Internet Research","topic":"数字心理干预","type":"系统综述与荟萃分析","title":"把行为激活搬到线上，哪些形式被真正测试过？","paperTitle":"Effectiveness of Digital Behavioral Activation Interventions for Depression and Anxiety","desc":"这篇系统综述纳入 18 篇论文、17 项随机试验，比较网络课程、电子消息和远程交付等行为激活。全文的时间分析显示抑郁症状在 2、3、6 个月有改善信号，12 个月不显著；生活质量与压力也呈现不同时间轨迹。","caveat":"研究包含的干预形态和人群不同，数字项目的平均结果不能自动代表某一款应用或每种服务模式。","url":"https://pubmed.ncbi.nlm.nih.gov/40526910/","fullTextUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12227033/"},{"id":"digital-eight-disorders","pmid":"40703853","year":"2025","journal":"Internet Interventions","topic":"数字心理干预","type":"多诊断荟萃分析","title":"同一张数字治疗地图，能覆盖八种心理障碍吗？","paperTitle":"Effectiveness of digital interventions for eight mental disorders: A meta-analytic synthesis","desc":"这项跨诊断荟萃分析纳入 168 项研究、22,144 名已确诊成人，比较八种障碍的数字干预。完整结果按对照和偏倚风险变化明显：广泛的总体效应并不等同于八种障碍都有同等可靠的临床证据。","caveat":"每类障碍纳入的试验数量、对照和指导方式不同；跨病种的合并结果不能当作统一的数字疗法效果。","url":"https://pubmed.ncbi.nlm.nih.gov/40703853/","fullTextUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12284662/"},{"id":"cbt-sleep-psychosis","pmid":"40401359","year":"2026","journal":"The British Journal of Psychiatry","topic":"精神病与睡眠","type":"系统综述","title":"精神病患者的睡眠问题，CBT-I 需要怎样调整？","paperTitle":"Cognitive behavioural therapy for sleep problems in psychosis: systematic review of effectiveness and acceptability","desc":"综述检索针对精神病患者或高风险人群的失眠认知行为治疗研究，也整理患者对治疗的体验、退出情况和方案改动。作者纳入 14 项研究，重点是标准 CBT-I 在这一人群里如何适配。","caveat":"纳入研究数量仍有限，方案与质量不一；摘要不能支持把某一套调整版方案视作已确立标准。","url":"https://pubmed.ncbi.nlm.nih.gov/40401359/","fullTextUrl":"https://www.cambridge.org/core/services/aop-cambridge-core/content/view/BE59FF0EE554DEED439135BC7C65FAFA/S0007125025000868a.pdf/div-class-title-cognitive-behavioural-therapy-for-sleep-problems-in-psychosis-systematic-review-of-effectiveness-and-acceptability-div.pdf"},{"id":"ceta-ipv-hiv","pmid":"41592903","year":"2026","journal":"BMJ Mental Health","topic":"创伤与心理治疗","type":"随机试验的次要结局分析","title":"在暴力经历与 HIV 照护交织时，心理治疗带来哪些变化？","paperTitle":"Effectiveness of the Common Elements Treatment Approach for mental and behavioural health outcomes among women struggling to remain adherent to HIV treatment and who have experienced intimate partner violence in South Africa: secondary outcomes from a randomised controlled trial","desc":"南非 399 名 HIV 照护困难且有近期亲密伴侣暴力经历的女性，被随机分到由非专科人员提供的 CETA 或主动对照。本篇报告抑郁和 PTSD 等次要结局；12 个月时两项症状都显示改善差异。","caveat":"本文分析的是次要心理结局；研究对象和服务情境具体，不能把发现概括为 CETA 对所有人际暴力经历者都同样有效。","url":"https://pubmed.ncbi.nlm.nih.gov/41592903/","fullTextUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12853443/"},{"id":"social-determinants-prevention","pmid":"40425198","year":"2025","journal":"BMJ Mental Health","topic":"心理健康预防","type":"系统综述与荟萃分析","title":"心理预防加上社会支持，能否减少心理障碍新发？","paperTitle":"Effectiveness of combining psychological prevention interventions with interventions that address the social determinants of mental health in low- and middle-income countries: a systematic review and meta-analysis","desc":"综述 21 个中低收入国家的 31 项随机试验，共 35,885 人，检验心理预防与应对社会处境因素的干预结合后，是否减少常见心理障碍。全文显示短期抑郁/PTSD 发生结局与症状分数需要分开读，长期信号主要限于儿童抑郁症状。","caveat":"焦虑发生率缺少可用数据；较长期的获益主要见于儿童抑郁症状，干预组合不能据此视作统一方案。","url":"https://pubmed.ncbi.nlm.nih.gov/40425198/","fullTextUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12107591/"}];
window.SOPHIA_BATCH_STORIES={"star-ptsd-psychosis":{"kicker":"当创伤记忆和精神病体验同时存在，治疗是否必须先等其中一个消失？","opening":"过去有一种谨慎做法：如果一个人仍有幻听、妄想等精神病体验，是否应该先稳定这些症状，再碰创伤记忆？这份顾虑可以理解，治疗师担心深入创伤会不会令情况恶化。但它也可能让 PTSD 长期得不到处理。英国 STAR 试验正面追问：把创伤治疗整合进精神病认知行为治疗，能否在不牺牲安全的前提下帮助这群常被排除在研究之外的人？","scene":"研究在英国五个地点招募 305 名同时患有 PTSD 与精神病的成人。他们都报告过反复、多重创伤。154 人接受为期九个月、个别化的创伤聚焦 CBTp 加常规照护；151 人继续常规照护。治疗不是把一套固定脚本强加给所有人，而是结合个人经历与当前困扰制定工作重点。","method":"研究采用评估者盲法：做主要 PTSD 评估的人尽量不知道参与者分组。主要结局是 9 个月时由临床人员使用 CAPS-5 评估的 PTSD 症状严重度；研究同时追踪精神病症状、情绪、心理恢复、社会功能与安全事件。开放心理治疗很难让患者和治疗师都不知道治疗内容，因此独立评估与长期随访尤其重要。","turn":"九个月时，整合治疗组的 PTSD 症状评分平均低 8.67 分，标准化效应量 d=-0.73。可评估的参与者中，治疗组约 50% 达到 PTSD 缓解，对照组约 22%。多个次要结局也出现有利差异，包括部分妄想、偏执、其他形式的幻觉、抑郁与焦虑；但研究报告的 27 个次要结局中有多重比较问题，作者未对这些分析作校正。声音幻听、参照观念、物质使用和社会功能则没有显示同样效果。","meaning":"故事最重要的转折不是“创伤治疗改善了一切”，而是创伤症状可以在精神病仍是临床现实的情况下被直接治疗。与此同时，症状改善并不自动带来社会功能提升；工作、关系和生活环境可能需要其他支持。治疗组有 94% 开始参与，95% 达到最低治疗剂量，说明这个高度复杂的治疗并非多数患者都无法接受。","clinic":"研究在专业团队和英国二级照护环境中实施，治疗持续九个月，评估者随访完成率也不是百分之百。结果支持临床团队不要仅因精神病诊断就预先拒绝创伤心理治疗，但不能简化成所有人都适合相同疗法、相同节奏。个体化评估、治疗师训练、共同决策和安全监测仍是方案的一部分。","close":"STAR 把一个常被当作“以后再处理”的问题带回眼前：如果创伤本身正在加重痛苦，等待精神病症状完全消失，是否反而让患者一直被困住？这项大型务实试验给了有力的积极信号，也清楚展示疗效不是全领域通吃。下一步要了解哪些人更需要何种支持、疗效能否维持，以及怎样让更多服务团队具备提供这类治疗的条件。","note":"全文核对说明：已对照论文全文的随机分组、治疗实施、4 与 9 个月结局及安全性结果。主要结局是 9 个月 PTSD 症状；27 项次要结局未校正多重比较，不能与主要结局同等确定。","headings":["那个一直被推迟的问题","305 位参与者的共同处境","这项治疗如何被放进常规照护","主要 PTSD 结局明显拉开","有效不等于所有生活领域都恢复","怎样理解对临床的意义","让被忽略的创伤获得治疗机会"],"readTime":"约 5 分钟"},"violence-nonspecialists":{"kicker":"当创伤后的痛苦离专科医院很远，谁还能伸出一只专业的手？","opening":"战争、流离失所或人际暴力之后，很多人需要心理帮助，却未必住在有足够精神卫生专科人员的地方。任务分担方案让受过训练、接受督导的非专科人员参与提供支持。争论不只是“这种办法能不能扩大覆盖”，还在于：面对暴力带来的复杂处境，它对症状和日常功能究竟有没有帮助？","scene":"这篇系统综述从七个数据库搜寻 2000 年至 2025 年的随机试验，筛查超过 54,000 条记录，最终纳入 45 项研究、9,431 名成人。参与者经历过战争或人际暴力，干预由非精神卫生专科提供者交付。研究把抑郁、PTSD、焦虑和功能损害分开汇总。","method":"研究团队在 7 个数据库检索 2000 年至 2025 年的随机试验，筛查 54,748 条记录，最后纳入 45 项研究。两位作者分别筛选和提取资料；四个主要结局是抑郁、创伤后应激、焦虑和功能损害的症状严重度，而不是各诊断的新发率。团队用随机效应模型合并结果，并按国家收入水平、服务场景、提供者、暴力类型和干预重点检查差异。论文也说明，研究方案没有让有心理健康困扰亲身经历的人参与。","turn":"四类结局的合并结果都偏向干预：焦虑标准化平均差 -0.44，抑郁 -0.41，PTSD -0.34，功能损害 -0.34。换成白话，这些是小到中等的平均差异，不表示每个人都改善相同幅度。敏感性分析方向大体相近；但研究间异质性达到 I²=77%–84%，44 项研究至少有某种偏倚风险。难民研究的平均效果较强，退伍军人结果未显著；这些亚组结果不等于已证明两类人必然有不同疗效。","meaning":"所以真正的发现不是“非专科人员对所有暴力幸存者都有效”，而是这种服务模式在广泛总体上有支持，同时不同处境可能需要不同方案。45 项研究中 44 项至少存在某种偏倚风险，主要结局异质性较高；一个漂亮的总体平均值，不能替代对具体项目质量和适配度的判断。","clinic":"非专科服务也不等于把复杂创伤问题交给未经支持的志愿者。培训、持续督导、转诊路径和明确的危机处置责任是模式的一部分。综述作者未纳入亲历者参与研究，这也是重要的知识缺口：服务怎样被体验、哪些做法让人感到安全，不能仅靠症状量表回答。","close":"这项综述像一张世界地图：大方向上，受训非专科人员能够成为心理照护的重要一环；但地图比例尺不够细，无法告诉每个社区照搬哪一种课程。下一步研究应把患者与幸存者参与、实施质量和不同暴力经历下的结果放在同一设计中，才可能从“平均有帮助”走向“怎样帮助到谁”。","note":"全文核对说明：已对照系统综述全文的检索、纳入标准、四类主要结局、异质性与偏倚风险结果。45 项研究的平均获益不能直接套用于某一种方案或某一位幸存者；研究未纳入亲历者参与。","headings":["心理服务的距离问题","45 项试验横跨不同处境","把很多不同项目合在一起","总体上出现了稳定的改善信号","平均效果背后有例外","“任务分担”仍需要专业支持","从总体趋势走向适配不同人群"],"readTime":"约 5 分钟"},"prenatal-digital-mindfulness":{"kicker":"一门手机里的正念课程，能陪孕妇睡过孕晚期吗？","opening":"孕期睡不好，常常不只是“晚上少睡几小时”。担忧会在夜里变得很响：担心自己睡不着，担心睡不好影响孩子，又因为努力入睡而越来越清醒。研究者据此设计了一个手机上的六周正念课程，想看它能否缓和孕期失眠，也想追问：如果睡前的担忧和身体唤醒降下来，失眠会不会跟着松动？\n\n这项研究的有意思之处，是它没有把结局停在课程结束那天。研究团队从孕中期开始观察，继续追到孕晚期，再到产后六周左右。结果有一个清楚的时间转折：课程结束和孕晚期时，失眠症状的组间差异还在；产后随访时，这种优势没有继续出现。","scene":"研究在中国山东两家三级医院开展。团队先筛查了 980 名孕妇，最后纳入 160 名有亚临床至临床失眠症状的参与者，平均年龄约 30.5 岁。她们被随机分到两组：一组使用针对孕期失眠设计的数字正念干预，同时接受标准照护；另一组接受标准照护。\n\n这不是对所有孕妇都有效的普遍测试。进入研究需要达到失眠量表门槛，也要符合具体的孕期和健康条件。研究结果回答的是：对这批孕妇来说，一套经过设计的六周手机课程加在标准照护之上，能否带来额外变化。","method":"研究把 160 人按 1:1 随机分组，由不知分组的评估者收集结果。干预通过手机或电脑上的微信平台提供，共六周，内容结合了正念练习与失眠行为策略，并针对孕期改写。比如练习会引导参与者觉察胎动；睡眠限制的最低卧床时间也根据既往孕妇研究设置。这里的“睡眠限制”是治疗方案中的行为方法，不是要求孕妇自行少睡。\n\n主要结局是失眠严重度指数（ISI）的变化。研究还测量睡眠效率、睡眠质量、疲劳、日间嗜睡、焦虑、抑郁，以及睡前担忧、反刍、唤醒等可能机制。所有这些结果主要由参与者在线自评；团队在干预结束、约两个月后（大致孕晚期）和产后约 42 天评估。研究没有用睡眠监测设备或临床诊断访谈替代自评量表。","turn":"平均而言，数字正念组在课程结束时的失眠症状下降幅度比标准照护组多 2.02 分；约两个月后、接近孕晚期时，差异仍是 2.02 分。标准化效应量 Cohen’s d 为 0.46，属于中等左右的组间差异。孕晚期时，数字课程组达到失眠缓解或可靠变化的可能性也更高。\n\n但这不是所有睡眠或情绪指标都一起改善的故事。多数次要结局没有显著组间差异；睡眠效率和睡眠质量在部分时间点有变化，经过多重比较调整后保留下来的差异更少。到了产后约 42 天，研究没有再观察到课程组的失眠优势。分析提示，睡眠相关担忧和睡前唤醒的变化可能参与孕期效果，但中介分析提供的是机制线索，不是已证明的因果链。","meaning":"这项试验真正提供的，是一个有时间范围的结果：对山东两家医院中符合条件的孕妇，六周数字正念课程在孕期带来额外的自评失眠改善，产后测量没有显示相同优势。不能把前半句剪出来写成“正念长期改善孕期睡眠”，也不能因为产后没有显著差异就断言课程完全无用。\n\n它同样没有证明睡前担忧就是唯一机制。研究测了多个认知和行为过程，主要支持的是睡眠担忧与唤醒可能解释一部分效果；同时，干预组和对照组在课程接触、期待和注意力上并不相同，这些因素也可能影响自评结果。","clinic":"对临床读者来说，这篇文章提示可以把“睡不好”进一步拆成失眠严重度、睡前担忧、夜间觉醒和日间影响，并关注孕期与产后是不同生活阶段。数字课程或许适合作为较容易接触的第一步，但这项研究并未与完整的治疗师主导 CBT-I 直接比较，也没有证明它适合所有孕妇或已达到特定诊断标准的患者。\n\n研究对象相对同质，失眠以量表筛查和自评为主，没有客观睡眠测量；数字课程的依从性也可能影响效果估计。若症状持续、明显损害功能或伴随严重情绪风险，不能把手机课程当作替代专业评估的办法。","close":"研究故事的最后一幕不是一个“应用有效”的大结论，而是一段具体的时间线：孕期有一段可测量的改善，产后没有维持同样的组间优势。接下来值得问的是，是否需要产后继续支持、哪些人最能从数字课程受益，以及量表变化能否转化成白天功能和真实生活的改善。\n\n这些问题还没有答案，但全文让我们看得更清楚：研究设计、测量方式、时间点和生活阶段共同决定了一项干预能讲出多大的故事。","note":"全文核对说明：已核对样本筛选、微信课程内容、随机分组、评估时间、效应估计及失访。主要结局为在线自评失眠；孕晚期的改善未在产后约 42 天延续，睡眠担忧与睡前唤醒的中介结果不能证明因果机制。","headings":["把孕期失眠当作值得处理的问题","160 人体验六周数字课程","研究如何追踪这段时间","孕晚期仍见到一些改善","产后这条线没有继续","数字支持的能力与边界","时间边界也是研究结果"],"readTime":"约 5 分钟"},"digital-behavioural-activation":{"kicker":"把“重新开始做点事”搬上网，改善能维持多久？","opening":"抑郁让人失去动力时，建议“多出去走走”听起来可能像责备。行为激活的核心不是催人振作，而是和治疗师一起发现回避与低落如何互相加固，再把有意义、可做到的小行动重新排进日常。数字版本有机会扩大服务，但线上课程、消息提醒和远程会谈并不是同一种东西。","scene":"系统综述找到 17 项随机试验，分为互联网课程、电子消息提示和远程治疗三类。有些方案只聚焦行为激活，有些把它与问题解决或认知行为治疗结合。研究除了抑郁与焦虑，还看生活质量、功能、压力和行为激活量表，试图呈现患者生活中不止症状的一面。","method":"12 项试验进入定量荟萃分析，其余以叙述方式总结。研究团队按 2、3、6、12 个月等时间点分别合并结果。这样的时间切片能让人看到变化轨迹，但不同研究的对照、参与者和数字交付方式差异仍然存在；时间点上的显著性不代表同一批人每个阶段都持续改善。","turn":"这 17 项随机试验给出的不是一个始终向上的疗效曲线。与对照相比，数字行为激活在干预后 2、3 和 6 个月与抑郁症状改善相关；到了 12 个月，差异不再显著，而且研究间差异很大（I²=89%）。生活质量在 3、6 个月有改善，压力在 3 个月有下降信号；焦虑、功能和残疾指标则没有稳定的显著差异。\n\n这个转折很重要：作者没有找到“所有生活领域都改善”的故事。12 项试验进入荟萃分析，其余以叙述方式整理；被合并的数字行为激活还包括单独模块和与问题解决、CBT 等结合的项目，所以不能把效果归到一个统一的线上课程。","meaning":"这个时间变化让问题从“数字行为激活有没有用”变成“哪种交付、持续多久、怎样维持”。短信提醒可能适合建立行动线索，完整网络治疗则可能需要结构、反馈与治疗师支持。把它们合并后得到的平均值不能回答某一款应用或某一种服务方案的效果。","clinic":"数字治疗的价值不只取决于理论内容，还要看是否有人能坚持、界面是否可用、遇到功能下降或风险上升时有没有人工接手。对于临床医生，这篇综述提供的是扩大可及性的证据线索，而非把面对面心理治疗一键替换成网页。严重抑郁、共病和自伤风险仍需适当评估。","close":"行为激活的故事本来就关于小步行动如何重新接回生活；数字形式则让我们追问，这些小步能否在治疗结束后继续。当前证据在几个月内较乐观，到了十二个月却不确定。更长随访和直接比较不同数字设计，才能告诉我们怎样把短期起步变成稳定的生活变化。","note":"全文核对说明：已对照综述全文的检索流程、试验数、干预形式、各随访时间点与异质性。12 个月抑郁结果不显著且研究间差异高；多数研究依赖自评，不能把短期平均差异写成长期维持。","headings":["为什么把行为激活搬到线上","不同形式被放在同一综述里","作者怎样汇总不同时间点","前几个月有信号，十二个月不确定","有效内容和交付方式难以拆开","数字服务如何接住真实需求","短期改善之后，怎样继续"],"readTime":"约 5 分钟"},"digital-eight-disorders":{"kicker":"八种障碍放进同一张图，比较起来会更清楚，还是更容易误会？","opening":"数字心理治疗常被宣传成一个大类，好像某种应用对焦虑有效，也能顺手解决失眠、强迫或 PTSD。但不同障碍的核心问题、治疗内容和需要的支持并不一样。研究者整理了八类已确诊成人的数字干预证据，想画出一张比较地图；地图能带来方向，也可能因为比例尺不同而让人误以为处处可比。","scene":"团队从持续更新的心理治疗数据库中整理随机试验，涵盖抑郁、失眠、恐惧、焦虑、强迫及创伤后应激等八类问题，并比较治疗师指导和无指导的项目。每一类疾病中的试验数、对照组、应用内容和随访安排都不一样。","method":"研究团队使用 Metapsy 的持续更新数据库，检索至 2023 年底、涵盖八种障碍的随机试验；最终纳入 168 项研究、22,144 人。分析采用多层荟萃方法处理同一研究中的多个结果，并按诊断分别估算，另做低偏倚研究、常规照护对照和有无治疗师指导等敏感性分析。研究者还用 GRADE 评估每种障碍的证据确定性，并公开了方案、分析计划和数据材料。","turn":"研究把 168 项研究、22,144 名已确诊患者放进统一分析框架，报告八种障碍的数字干预相对无活性对照有中等到较大的平均效应：PTSD g=0.57、抑郁 g=0.62、强迫症 g=0.68；广泛性焦虑 g=0.80、社交焦虑 g=0.84、失眠 g=0.94、惊恐障碍 g=1.05、特定恐惧 g=1.18。\n\n如果只看这组数字，容易得出“数字治疗对八种问题都很强”的印象。全文里的敏感性分析却让故事变得更复杂：低偏倚风险的证据下，只有抑郁、广泛性焦虑和恐惧仍能确认正向结果；与常规照护比较时，只有抑郁和失眠显示显著优势。多数研究的对照是等待名单，各病种研究质量和证据确定性也不相同。","meaning":"这篇综述像一张统一比例尺绘制的地图，优点是能把不同病种的证据缺口放在一起看；它不是八种疗法的公平擂台。平均效应主要来自与无活性对照的比较，而临床上更关心的往往是数字项目能否胜过常规照护。两种问题不能混为一谈。\n\n研究还发现，干预组退出率往往高于对照组；很多估计的证据确定性是低或极低。文章没有分析治疗次数、长期疗效或低中收入国家效果，处方数字疗法的识别也不是通过系统数据库搜索完成。","clinic":"数字干预可以成为治疗路径的一部分，但研究结论必须落到具体诊断、具体项目和具体对照上。作者指出，只有少数病种拥有低偏倚研究或与常规照护直接比较的足够资料；对无指导项目的证据尤其需要更高质量试验确认。产品进入服务前，还要考虑参与者能否持续使用、症状恶化时怎样转介，以及商业化产品的独立评估与利益冲突。","close":"一张八病种地图适合帮研究者发现空白，却不适合替代逐病种阅读。下一步的关键不是再把更多 app 放入同一个篮子，而是让试验报告干预组成、指导剂量、参与者特征和长期结局，并在同一疾病内进行公平的直接比较。","note":"全文核对说明：已对照 168 项研究、22,144 人的荟萃分析全文及偏倚敏感性分析。主要效应来自与非活性对照的比较；低偏倚研究与常规照护比较更少，GRADE 确定性因病种而异，不能据此为数字疗法排临床排行榜。","headings":["数字疗法不是一个单一疗法","八种障碍进入同一视野","跨病种综合的长处与难处","不同证据条件会改变结论","地图覆盖广，证据深浅不同","具体到临床该怎么选","更公平的比较还在后面"],"readTime":"约 5 分钟"},"cbt-sleep-psychosis":{"kicker":"精神病患者也会失眠：标准的失眠治疗要不要换一种讲法？","opening":"睡不着很常见，但当一个人同时经历幻听、妄想或其他精神病性体验时，失眠可能和药物、作息、焦虑、环境安全感交织在一起。标准失眠认知行为治疗 CBT-I 已有较成熟的做法，可临床团队会担心：睡眠限制等方法是否适合这类患者？治疗需要作哪些调整才更容易接受？","scene":"这篇系统综述纳入 14 项针对精神病患者或高风险人群的 CBT-I 研究，除了疗效，还整理可接受性、退出与方案修改。研究者试图超越“能不能降低失眠量表”这一问，看看治疗在服务中怎样被实际使用。","method":"研究团队按 PRISMA 流程检索四个数据库，先由两名研究者筛查题录，再由第一作者阅读所有候选全文、第二位研究者复核其中四分之一；最终 975 条记录中有 14 项研究符合标准。纳入研究包括随机与非随机干预研究，也包括患者对治疗体验的定性研究。作者分别整理睡眠、精神病及其他临床结局、退出率、不良事件与方案调整；质量评价也按研究设计使用相应工具。","turn":"全文里最具体的共同做法，是 CBT-I 研究常把“睡眠限制”删去或调整。睡眠限制本来是压缩卧床时间、提高睡眠驱动力的行为策略；但对精神病患者，治疗团队顾虑额外睡眠剥夺可能带来疲劳、警觉性下降或症状风险。综述报告睡眠结局的效应量在若干小型研究中较大，其他临床结局却没有同样清楚；定性访谈和可接受性问卷整体显示参与者评价偏正面。作者因此认为 CBT 对这类睡眠问题有前景，同时强调高质量研究少、样本小，仍需要更可靠试验。","meaning":"临床问题因此变得更细：睡眠困难可能是患者最想优先处理的痛苦，也可能与夜间症状、药物副作用或环境因素相连。治疗若只把“按时睡觉”当目标，可能错过真正让患者保持警觉的原因。反过来，因精神病诊断而完全不提供睡眠治疗，也会让一个可干预的问题被忽略。","clinic":"这篇综述不能替代个体评估。治疗设计应考虑当前症状稳定性、药物、认知负担、昼夜作息、居住环境和患者偏好；如采用 CBT-I 组件，应由受训团队根据人群特点作调整，并追踪日间功能与不良体验。是否需要睡眠医学或精神科协作，取决于具体情况。","close":"这 14 项研究打开了一道门，但没有把门后的走廊全部照亮。下一步要有更大的对照试验，明确写出如何调整治疗、哪些人被排除、患者觉得哪些部分有帮助，以及睡眠改善是否延伸到生活质量和精神症状。谨慎不是拒绝治疗，而是用更适合这群人的证据来设计治疗。","note":"全文核对说明：已核对四库检索、全文筛选与复核、14 项纳入研究、治疗调整和可接受性结果。部分研究报告较大睡眠效应，但样本小且质量参差，不能据此认定一种统一改编方案已确立。","headings":["失眠不因另一诊断而消失","14 项研究给出初步材料","不同版本的 CBT-I 怎样比较","还没有一个公认的调整模板","症状之间可能彼此牵连","治疗要回到个人处境","让睡眠治疗更贴合患者"],"readTime":"约 5 分钟"},"ceta-ipv-hiv":{"kicker":"当暴力经历和 HIV 治疗压力缠在一起，心理支持能改变什么？","opening":"有些女性面对的不只是抑郁或创伤症状。HIV 治疗依从困难、亲密关系中的暴力和安全风险可能同时出现；把这些问题拆到互不相干的门诊里，患者可能很难获得连贯支持。南非 CETA 试验尝试由受训的非专科人员提供跨诊断心理治疗，但这篇论文报告的是心理健康次要结局，主试验最初的问题与 HIV 照护有关。","scene":"研究在约翰内斯堡诊所招募 399 位女性，她们感染 HIV、存在病毒未抑制或依从困难风险，并在过去一年经历过亲密伴侣暴力。202 人分到 CETA，197 人分到主动对照；对照组得到短信预约提醒、简短安全检查与安全计划。","method":"研究在 3 个月和 12 个月评估暴力、抑郁、PTSD 与物质使用。CETA 是由非专科人员交付的共同要素治疗，按需要组合多个心理治疗模块。本文属于随机试验的次要结局分析；理解结果时要和主试验的主要问题区分，也要注意主动对照并非“什么支持都没有”。","turn":"研究纳入 399 名女性，202 人分到 CETA，197 人进入主动对照。CETA 组中 144 人（71.3%）完成课程，平均约 7.6 次、历时 12 周。三个月时抑郁差异还不确定；十二个月时，抑郁症状的组间平均变化差约为 -6.2 分，效应量 d=0.48。PTSD 症状在三个月和十二个月都显示差异，十二个月的效应量 d=0.47。\n\n但亲密伴侣暴力和物质使用没有出现显著组间改善。研究团队指出，入组要求是过去一年有暴力经历，可其中只有约三成报告过去三个月仍在经历或持续受到暴力；基线近期物质使用也不多。把抑郁、PTSD、安全和物质使用合并成一句“全面改善”，会掩盖不同结局各自的轨迹。","meaning":"这篇文章报告的是一项随机试验的次要心理结局。原试验的主要结局是 HIV 照护留治和病毒抑制，本文没有给出那个主要问题的结论。它显示在短信提醒、安全检查和安全计划等主动对照之上，增加由非专科咨询员实施的 CETA，可能带来抑郁与 PTSD 症状的改善；它没有证明暴力停止，也不能说明 HIV 主要结局改善。\n\n参与者和治疗团队没有盲法，所有心理结局由参与者自评。失访、对照中额外服务、以及暴力已经不是近期持续状态的人数较多，都会影响估计。","clinic":"这篇研究很重要的一点，是没有把暴力幸存者的心理治疗问题讲成“教她们更好应对”就结束。治疗应当由受训人员在督导下开展，并与安全计划、医疗照护及转介资源相连。结果只对应南非这一特定 HIV 与服务场景，不能直接推成所有暴力幸存者的普遍疗效。","close":"CETA 的故事显示，整合心理支持可能为抑郁和 PTSD 带来持续至一年左右的改善信号；同一方案却没有解决暴力与物质使用等结构性问题。下一步需要更有力的研究分别评估安全结局、治疗机制和 HIV 主要结局，并让亲历者参与设计，确保服务回应她们真正的优先事项。","note":"全文核对说明：已核对随机分配、主动短信与安全检查对照、干预剂量、失访处理及 3/12 个月估计。CETA 对抑郁与 PTSD 的组间差异在 12 个月更清晰；暴力和物质使用未显著，主要 HIV 结局不属于本文报告范围。","headings":["一位患者可能同时面对几种压力","南非诊所里的 399 位参与者","对照组也获得了安全支持","心理症状改善并不同步","症状改善不等于环境改变","整合治疗需要安全与转介","把心理结果放回更大的照护里"],"readTime":"约 5 分钟"},"social-determinants-prevention":{"kicker":"如果压力来自住房、收入和安全，心理预防能单独完成任务吗？","opening":"焦虑和抑郁常被描述成个人内部的问题，可生活压力可能来自贫困、暴力、住房不稳或缺乏安全的工作。心理预防教人识别和应对困扰；社会决定因素干预则试图改变造成压力的处境。把两者放在一起听起来更完整，这篇综述问的是：这种组合是否真的能减少常见心理障碍的发生？","scene":"研究者检索多个医学与试验注册数据库，纳入 21 个中低收入国家的 31 项随机对照试验，共 35,885 名参与者。干预将任务分担的心理预防和针对社会处境因素的措施结合起来，覆盖成人和儿童，并以新发常见心理障碍作为主要结局。","method":"团队检索多个数据库与试验注册平台，纳入 21 个中低收入国家的 31 项随机试验，并使用随机效应模型合并结果、以 GRADE 判断确定性。论文把主要结局“障碍发生/诊断”与次要结局“症状分数”分开处理；这很重要，因为平均症状下降不能直接说明新发诊断减少。研究中 13 项是面向成人、由社区工作者提供的家庭干预；各项目仍包含不同的心理技能、社会支持与实施场景。","turn":"作者从 21,780 条数据库记录中筛选出 31 项随机试验，覆盖 21 个中低收入国家、35,885 名成人与儿童青少年。多数项目由社区或基层人员提供，常把认知行为技巧与家庭支持、教育、社会联结或减少暴力等内容结合。\n\n主要结局显示，项目结束时抑郁和 PTSD 新发减少；次要结局则是另一幅图：成人和儿童的抑郁症状、焦虑症状有改善信号，儿童在 7–24 个月时仍有抑郁症状获益。没有可用数据评估焦虑障碍的新发率。作者因此把结论限定为“多数是短期的预防效果”，并呼吁比较不同项目和组件。","meaning":"“两种干预结合”不是一个固定配方。各研究里心理课程、社会支持、收入或服务措施可能各不相同，组合效果无法告诉我们哪一部分是关键，也无法确定加入社会层面措施是否优于单独心理支持。短期发生率结果积极，长期结果则更窄，时间边界必须保留。","clinic":"这项综述为跨部门预防提供了理由：如果困扰的一部分来自可改变的社会条件，只训练个人应对可能不够。但临床医生也不能把结构性问题全部转交给心理项目。社区、社会服务和医疗团队之间的合作，及可获得的转介与资源，决定了组合干预能否真实落地。","close":"研究把“让人更会应对”和“让生活少一些伤害”放在同一问题里。证据显示组合方案可能降低部分群体的短期障碍发生，但持续性与具体机制还不清楚。未来试验应直接比较组合与单项措施，并报告儿童、成人不同结局和更长随访，避免把复杂方案压成一个模糊标签。","note":"全文核对说明：已对照 31 项试验的年龄分组、主要发生率结局、症状次要结局、随访时间、异质性与 GRADE 局限。短期抑郁/PTSD 预防信号不能扩写成长期普遍保护；焦虑障碍发生率无可合并数据。","headings":["困扰有时来自个人之外","31 项试验覆盖 21 个国家","两种结局不能混为一谈","短期风险有下降信号","组合干预仍是一只黑箱","社会条件也属于照护背景","下一步要拆开组合看"],"readTime":"约 5 分钟"}};
window.SOPHIA_BATCH_EXPANSIONS={"star-ptsd-psychosis":{"contextTitle":"为什么创伤常常被放到“以后再说”","context":"STAR 的出发点，是精神病性体验与 PTSD 并不总是分开出现，而共存创伤症状会让病程和日常生活更复杂。临床团队可能担心，处理创伤记忆会不会加重精神病症状；研究者也指出，这类患者曾常被排除在创伤治疗研究之外。于是，一个看似谨慎的等待策略也可能变成长期没有针对性治疗。STAR 的问题不是“创伤治疗普遍有没有用”，而是能否把它改造成适配精神病照护的、灵活且个别化的方案，并在实际服务环境里检验效果与安全。","journeyTitle":"九个月里，研究不只等一个终点分数","journey":"305 名参与者被分到常规照护，或创伤聚焦治疗整合进精神病认知行为治疗并加上常规照护。团队在治疗中期四个月和九个月评估症状，主要结局由不知道分组的评估者使用临床访谈测量。这样的安排让读者能看到治疗进程，而不是只听到患者自己填写的一次问卷。研究也把 PTSD 缓解、不同症状群、精神病体验、情绪、恢复感和社会功能分开记录。生活经验顾问参与研究全过程，则帮助研究问题贴近当事人真正关心的处境。这个设计的长处，是把“治疗是否可接受”“症状是否变化”和“生活是否恢复”放进同一幅图。","reflectionTitle":"显著的主要结果，与不显著的生活功能要一起讲","reflection":"读完后可以把患者视角放回故事中心：如果一个人既经历创伤后痛苦，也有精神病性体验，她是否有机会参与关于治疗节奏的共同决定？哪些症状让她最难生活，哪些目标由她自己认为最重要？试验中的灵活治疗并非让患者独自面对创伤，而是在受训团队和常规照护中开展。推广时若缺少培训、督导和安全响应，照搬疗法名称并不能复制研究条件。更好的实践问题是怎样提供选择、监测过程，并让治疗目标覆盖创伤症状之外的社会功能和生活恢复。","turningTitle":"治疗没有要求患者先把另一种症状“解决好”","turning":"STAR 的临床问题触及一个常见的先后顺序：等精神病症状稳定，再谈创伤。试验却把创伤聚焦治疗嵌进精神病认知行为治疗，在九个月里按个人情况调整。参与者中大多数开始并达到最低治疗剂量，说明这项方案在专科团队里可以被接受。这个实施结果与症状结果相互补充：如果治疗没人愿意开始，再好的效应数字也很难落地；如果很多人能参加，也仍需看它有没有改善预先指定的临床结局。两条证据一起，才支持重新审视“先等一等”的默认做法。","humanQuestion":"这项研究触及一个容易被临床路径忽略的经历：一个人可以同时承受创伤后的反复回忆与精神病性体验，前者并不会因为后者出现就失去被认真处理的资格。把创伤治疗与 CBTp 接起来，传达的是“先一起理解，再共同选择”，而不是把人分成互不相干的诊断抽屉。研究结果的价值不在于宣布症状会被快速消除，而在于显示，经过训练的团队可以尝试直接提供创伤照护并进行严谨评估。","nextQuestion":"如果把故事继续往服务现场写，关键问题会变成：患者是否愿意谈创伤？治疗过程中怎样照顾安全感和节奏？治疗者如何在症状波动时与日常服务协调？论文的平均效果不能替某个人回答这些问题，也没有说明所有患者都该选择创伤治疗。它支持的是扩大可讨论的选项，让患者不再因为精神病性体验而被预先排除；决定是否开始、怎样开始，仍须由当事人与临床团队共同完成。","bridge":"把创伤治疗整合进 CBTp，意味着治疗师不把 PTSD 当作一个和当前照护无关的旧标签，而是尝试理解创伤记忆、当下解释和精神病性体验如何共同影响一个人的生活。研究中的方案以个体化 formulation 为基础，治疗持续九个月。这个安排本身传达了一种临床态度：不是要求所有人按同一脚本讲述创伤，而是通过共同理解逐步确定工作重点。生活经验顾问从研究阶段就参与，也帮助团队不只从症状量表出发定义问题。","afterthought":"这项试验的结果像一条有主有次的河流。主要 PTSD 结果方向清楚；其他二十多个结局中多数也偏向治疗，但由于未校正多重比较，不能把每条支流都当作同等牢靠的证据。更值得讲清的是，声音幻听、社会功能等结局没有同步改善。疗法针对创伤症状，并不承诺一次解决一个人的所有困难。对读者而言，保留这种不整齐比制造“全面康复”的完美结局更有帮助，也更尊重临床治疗通常需要多种支持并行的现实。","clinicalThread":"下一步的故事可以从研究参与者离开试验后开始：改善维持多久？患者能否持续获得创伤照护？哪些人需要额外康复、家庭或社会支持？当地没有九个月专科项目时，如何保留关键治疗成分而不降低安全性？论文让我们有理由重新审视排除这群患者的做法，但推广仍要靠服务能力、培训和当事人选择共同支撑。临床实践里可以把创伤治疗带入共同决策，而不是把试验结论变成所有人必须接受同一方案的规定。"},"violence-nonspecialists":{"contextTitle":"有创伤的人离服务很远，证据也曾离他们很远","context":"非专科人员提供的心理支持，在抑郁和焦虑等领域已有研究基础；但暴力经历者面对的风险、生活处境和服务需求更加多样，过去并不清楚总体效果能否沿用。本文因此把战争相关暴力与人际暴力经历都纳入检索，询问受训非专科人员能否帮助成年人缓解痛苦。这个问题背后还有现实的服务选择：如果专科人力不足，扩大支持是否能真正触达需要的人，同时仍保证转介、安全和照护质量？平均效果只能回答其中一部分。","journeyTitle":"五万多条记录，最后留下四十五项试验","journey":"综述从七个数据库筛查超过五万条记录，按预先说明的标准筛出 45 项研究。两位作者分别筛选和提取资料，再把抑郁、创伤后应激、焦虑和功能损害分开合并；团队还按服务地点、人员类型、暴力类型等寻找差异。这样做就像先画一张粗略世界地图，再放大看哪些地区与人群呈现不同图景。问题在于，地图上的每个研究并非同一种项目：训练、对照、文化语境和测量时间都不一样。因此研究越多，整体方向可能更清楚，具体某一种服务适合谁却未必更容易回答。","reflectionTitle":"总体平均是开门，不是把每个人都归进同一类","reflection":"这篇综述还留下一个不太舒服但重要的空白：作者说明没有让有亲身经历的心理健康服务使用者参与研究。对创伤照护而言，谁来决定什么叫有帮助、什么样的接触令人安全，不能只由症状量表替人回答。下一代项目可以让幸存者参与选择结局、调整培训和检查服务是否尊重自主权。与此同时，非专科人员需要持续督导、转介和危机支持。扩大服务覆盖不是把责任往基层推，而是把专业网络延伸到更靠近生活的地方。","turningTitle":"总体好转背后，读者要停下来看看谁没有同样获益","turning":"把 45 项研究合并后，焦虑、抑郁、创伤症状和功能损害整体都朝改善方向，且敏感性分析大致保持这个信号。这是一张有鼓舞力的大图。镜头放大后却能看到不同：难民亚组效果较强，退伍军人结果不显著，经历亲密伴侣暴力者的抑郁和焦虑也未见明确改善。亚组里“不显著”不等于证明毫无作用，但它至少阻止我们把总体均值当作每个群体的个人承诺。研究差异很大，统计平均背后藏着服务和人群的不同。","humanQuestion":"由非专科人员提供支持，首先是扩大心理照护可及性的设想，不应被理解为受暴力影响的人只需要低强度帮助。幸存者面对的处境可能仍在变化，心理痛苦也可能与安全、住房、经济和法律问题交织。综述中的平均改善信号说明这类服务值得认真研究；它没有说明所有人的需求都能由同一层级的服务满足。真正以人为中心的系统，必须让低门槛支持可以连接到更专门、全面的照护。","nextQuestion":"下一阶段研究可以把服务质量写细：人员接受什么训练、谁负责督导、怎样保护隐私、发现危险后如何升级处理，以及当事人是否觉得被尊重。结果也不能只由症状量表定义，还应包括安全感、日常功能、服务负担和求助过程中的伤害。作者指出缺少亲历者参与，提示未来研究需要让幸存者决定哪些问题最重要。扩大覆盖和听取当事人意见应当一起推进。","bridge":"筛查过程本身展示了这个主题有多广：研究团队先面对五万多条题录，再用明确标准保留成年人暴力经历、心理痛苦、随机试验和非专科交付等条件。综述还双人筛选和提取资料，尽量减少一个人的判断决定哪些研究进入。这样严谨的流程可以让总体估计更有依据，却无法让纳入的干预变成同一种疗法。每个国家的服务资源、暴力类型和提供者训练不同，因此这份综述回答的是“这一大类模式平均如何”，而不是“某个项目在你所在社区具体会如何”。","afterthought":"总体平均值有用，因为它告诉我们许多服务点的结果并非全靠单一研究支撑；异质性也高，因为不同试验处理的生活现实并不一样。研究报告的功能损害结局尤其值得看：心理支持不只要问症状少没少，还要问日常生活是否更能继续。可是量表无法代替当事人对安全、尊严和自主性的评价。综述没有亲历者参与，意味着这张地图主要由试验数据绘成，使用者如何感受服务仍是另一条需要补上的证据线。","clinicalThread":"若地方团队考虑采用非专科支持，最重要的不是把综述中的“平均有效”翻译成减少专业人员，而是弄清哪些人员经过什么训练、由谁督导、何时转诊以及风险事件怎样处理。对暴力幸存者，服务必须避免要求当事人重复讲述来证明自己，也不能把继续处于危险环境解释成治疗失败。后续研究仍应让幸存者参与设置结果目标，报告服务造成的负担或不良体验，并按暴力处境区分适配需求。只有这样，扩大覆盖才可能和照护质量一起前进。"},"prenatal-digital-mindfulness":{"contextTitle":"孕期可用的低门槛支持，为什么值得研究","context":"论文指出，孕期失眠症状常见、可能带来明显负担，却并不总能获得有实证支持又容易接触的干预。数字正念课程看起来可以跨越预约和地点限制，但“方便打开”不等于“能坚持使用”，也不等于疗效能覆盖不同生活阶段。研究者特别关心睡眠担忧、反刍、睡前唤醒和不良行为习惯，因为这些过程可能让失眠持续。于是这项试验既问课程是否改变睡眠，也尝试追踪哪些认知与行为过程可能随之变化。","journeyTitle":"从课程结束，一直追到产后六周","journey":"160 名有亚临床到临床程度失眠症状的孕妇被随机分组，一边接受六周数字正念项目加标准照护，一边接受标准照护。研究团队没有只在课程结束时测一次，而是在干预后、约两个月后（大约进入孕晚期）以及产后 42 天继续通过网络问卷追踪。这个时间线让一个短项目必须面对生活阶段变化的考验：如果孕期分数下降，之后是否维持？研究同时记录了睡眠、疲劳、白天嗜睡、焦虑和抑郁等多项结果，但大多数副结局没有稳定的组间差异。所有结果均来自线上自评，而非睡眠实验室测量。","reflectionTitle":"产后没有延续同样的差异，也是故事的一部分","reflection":"数字课程可以降低开始练习的门槛，却无法仅凭一次开发就覆盖孕期到产后的所有需要。若未来方案增加产后复习、同伴支持或人工随访，那将是值得测试的新设计，并非本研究已证明的补救办法。还需要知道哪些参与者完整使用了课程、没有回应问卷的人后来怎样，以及症状改善有没有转化为白天功能变化。把时间轴画出来，就不容易把一个时间点的显著差异扩写成长期保证，也能帮助服务团队决定何时需要继续联系而不是发完课程就结束。","turningTitle":"产后随访让故事多了一个重要的时间转场","turning":"如果研究在六周课程结束时就停下，读者可能只会看到一个正向结局。团队继续追到大约孕晚期和产后 42 天，结果揭示改善并未在每个时点都保持同样差异。这个转场很有意义：怀孕后期与产后不仅时间不同，生活安排也可能改变，而干预内容没有自动跟着这些现实转变。论文数据显示，孕晚期的失眠改善更稳定；多数其他结局却没有同样一致的变化。读者由此能看见研究里“什么时候有效”有时和“是否有效”一样重要。","humanQuestion":"手机课程看起来轻便，但“容易打开”与“真正得到支持”不是一回事。数字正念项目也许减少了往返服务的负担；同时，独自完成、注意力被打断、缺少个别回应，都可能让体验和面对面支持不同。研究发现孕期某些测量有改善、产后没有相同组间获益，提醒我们把时间线讲完整：人在不同阶段经历的变化，未必由同一种方式稳定承接。","nextQuestion":"如果要把数字项目发展成可靠服务，下一步应问谁能坚持、谁会中途退出，课程哪些部分被实际使用，以及产后支持是否需要另行设计。还要看症状之外的日间功能和患者感受。短期统计差异不应被包装成长期治疗承诺。对临床团队，这篇研究可作为讨论数字支持的一扇窗口；是否适合个人，仍取决于症状评估、偏好、安全和其他照护安排。","bridge":"这个研究不是直接把普通冥想应用发给参与者，而是设计了针对孕期失眠的六周数字项目，并与标准照护比较。团队把睡眠担忧、睡前唤醒、注意偏向和不适应行为列为可能机制，说明课程背后有明确假设。所有结局由参与者通过网页问卷填写，优点是便于多时间点追踪，限制则是主观报告不能代替睡眠设备记录。这个差异不代表自评“不可靠”，而是它主要告诉我们参与者怎样体验自己的睡眠。","afterthought":"产后没有出现同样组间优势，是理解干预时间边界的关键。课程可能在孕期那段时间帮助一些人，却没能自然跟上分娩后的生活变化；也可能是产后测量精度不足或其他因素影响。论文无法替我们在这些解释中选一个。正因如此，故事不能在课程结束时画上句号，而要看孕晚期、产后、白天疲劳和家庭生活是否相互影响。研究把“效果能不能延续”变成可观察的问题，是比单次显著结果更有用的设计。","clinicalThread":"如果数字课程作为第一步支持，它仍需要说明什么情况适合自助练习、症状加重时找谁、怎样转到专业服务。对于有明显抑郁、严重焦虑或风险的孕产妇，数字项目不能延误必要评估。后续研究可以比较延长课程、增加人工反馈或设置产后复习的效果，但这些都属于未来方案，当前试验没有测试。把便利性与连续照护放在一起规划，才能让技术服务不只容易开始，也能在需要时继续接住人。"},"digital-behavioural-activation":{"contextTitle":"从“没力气做事”到“更没机会好起来”的循环","context":"行为激活的出发点很生活化：低落会让人减少活动、退出关系或暂时放弃原本有意义的事情；活动减少后，得到积极反馈的机会也变少，低落可能因此维持。把这一循环拆小，逐渐重新安排可完成的行动，是行为激活的核心思路。数字形式让练习可以通过课程、提醒或远程支持交付，但名字相同不代表体验相同。综述于是把线上课程、电子消息和远程治疗等不同形式纳入，关心的不只是症状分数，也包括功能与生活质量。","journeyTitle":"综述面对的不是一个 App，而是一整个工具箱","journey":"17 项随机试验里的项目在交付方式、治疗师参与和对照条件上各有差异。作者把它们归到数字行为激活这个共同框架下，再分别看抑郁、焦虑、生活质量、功能和压力。这个过程像把外观不同的工具放在桌上，先看看它们是否真在做相近的事，再估计整体方向。合并分析能回答“这个领域平均如何”，却不能替某个具体产品背书。参与者有没有完成活动、提醒能否形成持续练习、遇到困难时有没有真人回应，都会影响真实使用体验，而这些细节不一定能被一个总效应量呈现。","reflectionTitle":"症状分数只是生活故事的一部分","reflection":"未来更好的试验可以把“使用了几次”与“恢复了什么活动”分开报告，问参与者哪些行动由自己选择、遇到障碍时课程是否帮助他们调整。抑郁和焦虑的症状量表之外，功能、生活质量及效果维持都需要时间线。临床团队也要关注未能参与课程的人是不是因为设备、网络、语言或注意力负担而被落下。若产品更新了内容，旧版本试验的结果不能自动转移过去。故事真正关心的不是技术有多新，而是它有没有帮助人重回自己在意的生活。","turningTitle":"行为激活的核心不是提醒，而是行动重新连上意义","turning":"在一款应用里设置待办提醒，很容易被误认为行为激活。真正的治疗过程通常要先理解低落时哪些活动逐渐消失，再找出对个人有意义、现实中能迈出的下一步，并回看行动和情绪如何互相影响。综述把不同线上方式合并，能告诉我们这个治疗家族的平均结果，却不能确认每个项目都保留了这些关键环节。提醒很多、完成任务很多，也不一定代表生活的正反馈真的回来。这样区分，能让数字工具的功能不被包装词汇替代。","humanQuestion":"行为激活背后的直觉很朴素：情绪低落时，人可能逐渐退出原本有意义的活动，进一步减少接触愉快或有掌控感的经历。帮助人重新安排小而可行的行动，是让生活重新出现反馈的尝试。数字形式把支持放进手机或网络课程里，可能更容易接触，却不代表完成课程就等于恢复日常生活。真正重要的是参与者能否找到对自己有意义、也能做到的行动。","nextQuestion":"未来研究可以把“用了多少课程”与“生活里发生了什么”分开报告，追踪活动、功能、症状及退出原因，并明确数字项目有没有真人陪伴。服务机构还应确认项目适合的症状范围，风险升高时如何转到真人照护。对读者而言，这篇研究提供数字行为激活的证据线索，也提醒我们建议必须贴合个人资源和处境，不能把结构困难说成缺乏积极性。","bridge":"数字课程的共同标签可能掩盖治疗过程的差异：有的项目主要提供自助材料，有的安排消息提醒，有的则由治疗师远程带领。对于行为激活，关键不只是页面上有没有活动清单，而是参与者是否能识别自己的低落—退缩循环，选出有意义的行动并根据结果调整。不同交付方式在这条过程中提供的支持并不相同。把研究放在一个综述里可以看大方向，却需要回到具体项目才能知道对谁更有帮助。","afterthought":"作者把功能、生活质量和压力也纳入，是为了追问症状变化之外的事情。若一个人抑郁分数下降了，但仍无法回到在意的活动，治疗故事还没有写完；若她的日常行动变多，即使总分变化不大，生活也可能出现重要转折。研究汇总不能替患者决定哪个结局最重要，但可以促使试验不要只报告一个量表。未来研究应把活动完成、患者选择、指导强度和长期维持连起来看。","clinicalThread":"将项目带进门诊或社区时，可以把应用当成共同工作的工具，而非向患者派发的作业。治疗者需要了解活动为何重要、现实阻碍是什么，并在患者做不到时调整计划，而不是把未完成当作缺乏动力。数字形式可能方便，也可能让没有稳定设备、网络或私人空间的人更难参与。下一步试验应把这些可及性问题写入结果，让我们知道平均效果背后是谁能真正用上服务，谁被技术门槛挡在外面。"},"digital-eight-disorders":{"contextTitle":"同一个屏幕里，可能装着八种完全不同的问题","context":"数字心理干预容易被讨论成一个统一类别，好像只要能在线使用，就可以用同一套证据判断。但失眠、抑郁、焦虑、强迫、创伤相关问题和恐惧等障碍，治疗目标和风险并不相同；数字课程中有没有治疗师、内容是否针对诊断，也会改变它到底是什么。研究团队把八种障碍分开做合并，希望画出证据版图，而不是宣布一个适用于所有人的“数字疗法”。","journeyTitle":"先分地图，再比较路线","journey":"这篇综合分析从已确诊成人的数字治疗试验中提取资料，按障碍类别汇总，并比较有无治疗师指导的项目。作者面对的核心难题，是每一类病症下试验数量、对照方案和人工支持并不均匀。某一疾病的效果较清楚，不代表另一疾病可以借用；某个亚组的指导优势，也可能受试验设计差异影响。分层分析让读者看见领域内部的差别，但样本少或证据不齐时，估计会变得不稳定。要读出真正含义，得先看清每一条路线的起点和终点。","reflectionTitle":"不能让“数字治疗”这个总标签替产品作证","reflection":"这张地图能帮助机构决定下一项研究该补哪里，却不足以决定某个患者今天该下载什么应用。需要核对的不只是诊断名称，也包括项目具体版本、治疗师指导内容、遇到症状恶化时的支持和患者的使用偏好。试验可以显示一个平均差异，却未必告诉我们产品如何融入真实服务、需要多长时间以及成本由谁承担。让数字干预走向常规照护，需要从“看起来有效”再走几步：可复制、可监测、对目标人群有帮助，并且出现风险时有人接得住。","turningTitle":"跨诊断比较的价值，是找出空白而非造一个总冠军","turning":"把八种障碍放入同一套分析，能让人看见数字干预研究的广度；但每一类里试验数量和对照条件不一样，所谓“总体比较”必须拆回具体病种。某种治疗师指导方式在一组研究里呈现优势，可能与支持强度、疗程或参与者严重程度有关，并不只是多了一个聊天窗口。若读者把综合分析当成八种病共同的治疗指南，就会把研究者努力保留的分层重新抹平。更有用的读法，是找到哪几类证据较多、哪几类还需要更严谨试验。","humanQuestion":"当同一种数字形式被用于多种诊断时，最容易发生的误解是把“数字治疗”当成一个统一疗法。屏幕只是交付方式，真正发挥作用的可能是不同的内容、练习、反馈或治疗关系。八类问题放进一篇分析里，价值是看到整体研究版图；风险则是把跨类别的平均结果搬到具体患者身上。每个病种都要回到自己的研究数量和干预内容来理解。","nextQuestion":"未来比较需要描述产品版本、使用强度、治疗者支持和临床风险，而不仅写一个项目名称。还要检验患者能否使用、遇到困难能否求助，以及症状以外的功能是否变化。机构选择工具时，可以先从特定需求和证据出发，而不是先问哪个应用排名最高。这篇分析帮助寻找研究线索，不等于给所有诊断开了一张通用数字处方。","bridge":"跨诊断综合分析像把不同城市的交通图摊在同一张桌上：能比较路线的共同点，却不能因为都画着道路就说每种城市都能使用同一交通方案。数字失眠项目可能围绕睡眠节律，数字抑郁项目可能安排活动，焦虑或创伤项目又可能需要不同风险支持。研究团队按障碍类别分层，是在努力保留这些区别。可是当某一类别试验少、治疗师指导的定义不统一时，分层结果仍可能很不精确。","afterthought":"这篇研究的一个用途，是帮助研究者找出证据空白：哪些障碍有足够随机试验可以进一步比较，哪些只是有零星项目值得验证。它不应该变成数字治疗排行榜，特别是当每一类里的产品、对照和随访都不一样。即使有指导项目表现较好，也要知道指导是每周会谈、文字反馈还是提醒；没有这些内容，服务机构很难复制。读者可以沿着每个病种单独追问，而不是把八个章节折叠成一个“线上方式有效”的结论。","clinicalThread":"机构若考虑部署数字治疗，应该先确认需求类别与方案证据相符，再看产品如何升级、是否保护隐私、遇到危机时谁接手，以及患者是否愿意使用。研究者则需要更标准化地描述干预版本和治疗师参与，避免同一名称覆盖完全不同的服务。数字形式可能扩大服务覆盖，但覆盖人数本身不是临床获益。把可实施性、功能和安全一起纳入研究，才能说明这项技术该放在预防、辅助照护还是特定治疗位置。"},"cbt-sleep-psychosis":{"contextTitle":"失眠可以困住人，治疗本身也得适合他的处境","context":"失眠认知行为治疗有明确的行为和认知练习，但精神病相关人群可能同时面对药物影响、日间嗜睡、症状波动或较不稳定的生活环境。把普通失眠项目原样搬过来，未必能回应这些复杂因素；反过来，担心不适配而完全不谈睡眠，也会漏掉一个可能影响日常状态的困扰。综述因此同时关注疗效与可接受性：患者是否愿意参与、实际方案如何调整，与量表有没有下降一样值得了解。","journeyTitle":"14 项研究，拼出的还是一幅不完整图","journey":"作者检索针对精神病患者或高风险人群的失眠 CBT 研究，纳入 14 项并整理患者体验、退出情况和方案调整。研究数量比单个试验多，却不意味着已有一个统一版本可以直接推广。不同研究可能采用不同形式、样本和质量；有些报告能说清治疗怎样改，有些细节则不足。综述把这些信息并在一起，就像先检查一条路是否有人走过、是否有人中途离开，再问走到终点后睡眠是否变化。疗效与“是否能实际开展”要同时看，但可行性信号并不能替代高质量对照试验。","reflectionTitle":"真正需要回答的，是怎样调整而不是要不要睡眠治疗","reflection":"未来若要建立可靠的适配版本，应把患者和照护者的经验纳入设计，明确症状波动时如何调整、哪些练习可选、怎样和药物团队协作。也要观察睡眠改善之后白天精力、认知和生活功能是否变化，以及这些变化能否维持。论文的结论不能被说成所有精神病患者都应接受同一套 CBT-I；但它也不支持把失眠留在服务议程之外。临床上的故事可以从一句“最近夜里怎么样”开始，然后和患者一起决定需不需要进一步评估和哪种治疗尝试。","turningTitle":"接受治疗和从治疗中获益，是两道不同的门","turning":"综述同时整理效果和可接受性，是因为睡眠方案即便逻辑清楚，如果患者觉得负担太大、治疗者不熟悉调整方式，实际服务中也难以持续。退出率、参与者体验和哪些模块被改动，常常比一个汇总分数更能告诉我们方案是否适配精神病服务。14 项研究只足以提供早期方向，不能保证每种改编都等价，也不能确认患者退出是因为方案无效、实施困难还是其他生活因素。读者需要看到这些“过程线索”与结果一起出现。","humanQuestion":"在精神病照护中问睡眠，不是把一切症状都归结为睡眠，也不是暗示患者只要睡好就会康复。它是承认夜间困扰本身可能很消耗人，并值得作为照护目标被讨论。CBT-I 需要结合患者现实来调整，尤其当白天疲惫、药物影响或其他症状也在场时。综述把这类研究汇总，意义在于让睡眠治疗成为可研究、可共同决策的选项，而不是让患者独自面对失眠。","nextQuestion":"目前证据仍需要更完整描述具体适配、随访和患者接受度。未来试验应区分睡眠改善是否带来白天功能变化，也说明哪些成分对安全和疗效最关键。临床上可先听患者如何描述睡不着、何时开始、最想改善什么，再考虑评估或治疗。论文提供继续研究的理由，不是一个可不经评估直接套用的统一程序。","bridge":"“适配”往往藏在治疗细节里。睡眠限制、刺激控制、认知练习等模块怎样安排？如果患者白天很困，是否要调整节奏？治疗者如何和精神病服务团队交流？综述整理这些方案变化，正是因为治疗名称不足以描述患者实际接受的内容。纳入研究也考察退出和接受程度，让我们知道有人是否愿意继续，而非只看完成者最后的量表。全文逐项整理了这些修改，但原始研究对调整理由和实施细节报告不一，后续研究仍需更完整记录。","afterthought":"若不同研究都说使用了 CBT-I，却只有一部分明确报告适配方式，综述就很难告诉临床团队该复制哪个版本。这不是患者群体“太复杂所以无法研究”，而是需要更清楚地写出治疗过程。未来试验可以设置标准模块与个别调整记录，让读者知道哪些步骤不可少、哪些因患者目标而变化。患者感到安全和可接受，也应成为研究结果的一部分。这样，疗效问题才会从一个抽象的平均分，变成临床团队能讨论的具体治疗过程。","clinicalThread":"把睡眠重新带进照护对话，不必从一开始就承诺某个完整疗法。可以先了解失眠何时出现、患者认为它和症状或药物有什么联系、白天最受影响的是什么，再共同考虑专业评估和治疗选择。这样做并不是由一篇综述替个人开立方案，而是把一个常被漏问的问题交还给患者。研究的下一步也应该检验这些对话和适配是否提高参与度、睡眠及日常功能，同时确保心理和药物照护彼此协同。"},"ceta-ipv-hiv":{"contextTitle":"当暴力、情绪和身体治疗同时拉扯注意力","context":"这项研究把视线放在南非诊所中一群处境具体的女性：她们与 HIV 共处，病毒载量未抑制或有依从风险，同时经历过近期亲密伴侣暴力。暴力与情绪困扰和医疗结局彼此牵连，但一个人实际面对的可能是预约提醒、安全风险、治疗中断和创伤症状同时出现。CETA 由受训非专科人员交付，尝试按问题组合常见治疗模块。它是否能改善心理结局，必须放回这套医疗与安全支持的现实里理解。","journeyTitle":"主动对照组也在提供具体支持","journey":"399 名参与者随机分到 CETA 或主动注意力对照；对照组收到 HIV 预约短信提醒，并接受安全检查和计划。因此研究比较的不是“有人帮助”与“完全无人照料”，而是在已有支持基础上增加 CETA 会有什么变化。论文报告三个月和十二个月的抑郁、PTSD、暴力和物质使用等次要结局；主要试验关注 HIV 留治和病毒抑制，本文并不是那个主要结果的完整报告。把对照内容和结局层级看清楚，才能知道哪些发现适合讲成主要证据，哪些仍只是额外的临床线索。","reflectionTitle":"心理症状变好，不代表暴力风险已经消失","reflection":"主动对照中的短信提醒和安全检查同样重要：它们说明控制组并非毫无支持，CETA 的效果是在这些措施之上估算出来。若未来服务采用整合治疗，还需要与 HIV 照护、暴力安全资源及患者自主选择相协调。研究没有说明心理治疗能阻止施暴，也没有替主要 HIV 结局下结论。更完整的照护叙事应当同时问：症状是否减轻、患者是否更容易留在医疗服务中、外部安全有没有改善，以及她本人希望下一步得到什么帮助。","turningTitle":"心理结局有变化，暴力结局却没有同样变化","turning":"抑郁和 PTSD 在三个月有信号，到十二个月差异更清晰；物质使用与亲密伴侣暴力则没有显著组间变化。研究报告基线时近期物质使用者比例较低，暴力结局的测量范围也有限，这让未见差异很难直接解释成治疗完全无效。另一方面，症状改善也不能被扩写成风险环境已经改变。把不同结局分别读，会比一句“CETA 有效”更能保留女性真实面对的多条问题线索。","humanQuestion":"当心理支持进入 HIV 照护与亲密伴侣暴力的交叉处，症状并非唯一重要的事。患者可能同时需要持续医疗、隐私保护、安全计划和可以信任的支持者。CETA 试验中的心理结局提供了关于痛苦变化的线索，却不能让我们把暴力风险、病毒学结局和心理症状揉成一个“干预有效”的判断。不同目标可能沿不同时间线变化，也需要不同服务负责承接。","nextQuestion":"下一步应研究怎样把心理治疗和安全、医疗、社会支持稳妥连接，并让经历者参与决定何种改善有意义。报告中还要区分治疗本身、简讯与安全检查等支持条件。临床上，抑郁或 PTSD 改善值得肯定，但必须继续单独询问安全、医疗连续性和患者需要。一个服务不能被要求替代另一个系统；协作照护才可能让不同需求都有人回应。","bridge":"试验的控制条件包括预约短信和安全检查，因此两组都处在一项关注 HIV 治疗连续性与暴力安全的研究环境中。CETA 是额外加入的、由 lay provider 提供的心理治疗，而不是孤立发生在真实生活之外的实验活动。研究者选择报告抑郁、PTSD、暴力和物质使用等次要结局，让我们看到心理层面的轨迹；但这些结局不能代替原主要试验的 HIV 留治与病毒抑制结果。","afterthought":"抑郁与 PTSD 的差异在较长时间点更清晰，可能提示干预收益需要一定过程才显现；但如果不对照具体支持内容，也不能把所有变化都归于 CETA 的某个单独模块。暴力结局不显著更提醒我们，心理治疗缓解痛苦并不等于关系中的风险消失。临床服务要避免把“症状变轻”当作安全已经解决。将多个结局分别讲清楚，既能肯定心理支持的价值，也不把它夸成可以替代社会、法律和医疗资源的万能办法。","clinicalThread":"读到这项研究时，可以把患者生活想成不止一条同时行进的轨道：治疗依从、情绪、创伤反应、安全和物质使用。某一轨道改善，不保证其他轨道同步变化。后续工作需要有足够样本去分析暴力和物质使用结果，并保留主动安全支持；亲历者的声音也应参与决定什么算有意义的变化。对服务团队来说，这意味着心理治疗要被嵌在更广的照护关系里，而不能让患者独自承担不同系统之间的衔接。"},"social-determinants-prevention":{"contextTitle":"如果压力来自生活条件，预防还要只教个人应对吗","context":"心理健康预防项目常训练应对技能，但生活中的压力还可能来自住房、收入、教育或社会排斥等更大的条件。只靠个体心理练习，可能没有触及压力的来源；只做社会支持，也未必回应症状和求助需要。研究团队因此把两类干预组合起来研究，尤其关注中低收入国家的常见心理障碍发生风险。这个视角把预防从“一个人学会调节”扩展为“服务和环境怎样一起改变风险”，但也让干预本身更加多样、评估更复杂。","journeyTitle":"三万多人参与，组合里仍有很多不同答案","journey":"综述从两万多条记录中筛出 21 个国家的 31 项随机试验，共 35,885 人。研究把心理预防与应对社会决定因素的干预结合后，与控制条件比较，并区分成人、儿童、干预结束时及较长随访的结果。这个时间线至关重要：短期新发风险下降，不自动意味着一年后同样维持；不同组合的平均效果，也不能说明究竟是哪一个组件发挥作用。研究使用随机效应模型并评估证据确定性，试图承认试验之间存在差异，而不是把所有项目想成同一套方案。","reflectionTitle":"短期预防的信号，不能被讲成长期保护承诺","reflection":"若服务部门想复制组合项目，还必须问心理课程和社会支持各自如何实施、需要什么人力、项目结束后谁继续提供帮助。综述显示组合有潜力，却没有告诉我们每种组合都一样，也没法从总体结果推算某个社区的成本收益。下一步直接比较组合与单项干预会更有解释力。更长随访则可以观察预防是不是真的改变了生活轨迹。心理健康预防的故事不能只发生在治疗教室里，也要看到住房、资源和持续服务条件如何参与其中。","turningTitle":"时间一拉长，获益范围就变窄了","turning":"短期分析显示成人和儿童的抑郁及 PTSD 发生风险下降；追到七至二十四个月，比较明确的信号主要剩在儿童抑郁症状。这个时间转场告诉我们，预防效果不是一个永久标签：项目结束时的保护可能减弱，也可能长期结局资料不足。作者还指出没有焦虑发生率数据，因此无法补出一个完整的心理障碍预防故事。将缺失写进结论，不是削弱研究，而是让后来设计试验的人知道要延长追踪哪些结局。","humanQuestion":"心理预防如果只训练个人如何调节情绪，却不看压力从何而来，可能会错过人们生活里更大的限制。社会决定因素研究试着把个人技能与环境资源放在同一张图上，但不同项目组合差异很大，因此“包含社会因素”不是一种可直接复制的单一疗法。综述的价值，是把注意力带向风险如何在生活条件中形成，同时提醒我们试验尚未告诉每个组成部分的独立作用。","nextQuestion":"研究应和社区一起定义压力与支持，追踪服务是否真正到达目标人群，并观察项目结束后资源是否仍在。症状之外，功能、归属感和现实生活条件也可能重要。预防不是要求个人更能忍受不利环境；它应该与可获得的社会支持相连。综述提出继续比较具体组件的方向，本身不证明某项政策或项目已被验证。政策决策仍需本地数据、资源评估和受影响群体参与。","bridge":"把社会决定因素纳入心理预防，意味着项目可能同时包含个人技能课程、社区支持、经济或服务资源等不同组成。它们的共同点是试图降低风险，但实现路径并不一样。综述把组合方案与控制条件比较，能回答“这些策略一起出现时平均发生了什么”，不能拆出住房支持或心理教育各自的独立贡献。这也是为什么作者将下一步研究重点放在组件与头对头比较，而不是宣称一种统一干预已经适用于所有地区。","afterthought":"成人与儿童在短期风险结果上都出现信号，较长随访却只对儿童抑郁症状保留更明确的获益。这样的差别让研究结果更像一条时间线，而不是一枚“有效”印章。预防项目可能需要持续支持，也可能因人群和生活条件而产生不同效果；当前资料不足以确定哪种解释更正确。知道哪些结果尚不可得，例如焦虑发生率没有数据，能帮助下一项研究避免继续留下相同的空白。","clinicalThread":"如果一个地区要设计预防服务，项目应与当地社区共同确定生活压力和可获得资源，不把结构性问题说成个体没有韧性。还要跟踪参与者是否真的得到资源、项目结束后是否仍然可及，以及情绪与生活功能怎样变化。这些实施问题不是荟萃分析能替本地服务回答的。把心理工具和社会支持放在一起，理论上更贴近人的生活；让它持续有效，则还需要资源、责任人和可持续的政策环境。"}};
window.SOPHIA_BATCH_DEPTH={"star-ptsd-psychosis":{"heading":"为什么“次要结局”要慢一点读","text":"STAR 的主要问题是 PTSD 症状有没有改善，研究为这个结局预先安排了评估，因此主要结果最能支撑论文的核心判断。妄想、抑郁、焦虑等结果则属于次要结局：它们能帮助我们观察治疗可能产生的更广泛影响，但项目同时检查很多指标时，偶然出现显著差异的机会也会上升。作者没有校正多重比较，所以这些结果适合作为后续研究线索，不应该与主要 PTSD 结果放在同一确定性层级。","nextHeading":"积极结果仍留下的临床问题","next":"治疗组完成率说明这类治疗在专科团队里可以实施，但“可实施”并不自动回答真实世界普及后能否维持质量。团队需要训练、督导、患者安全管理和足够疗程。下一步还应观察 PTSD 改善是否长期持续、生活功能能否后来跟上，以及哪些患者更愿意接受这种方式。研究的价值不是宣布一个通用答案，而是让临床团队重新检查：精神病体验本身是否应该成为不提供创伤治疗的默认理由。"},"violence-nonspecialists":{"heading":"平均改善背后，方案并不是同一种治疗","text":"这 45 项研究覆盖战争、社区暴力和人际暴力等不同经历，也使用多种心理社会方案。合并后看到焦虑、抑郁、创伤症状和功能方面的平均改善，说明受训非专科人员提供支持可能扩大服务可及性；但读者不能把这个平均数理解为每一种方案、每一个地区或每位经历暴力的人都会有同样效果。研究间的人群、培训、督导、对照和随访不同，合并结论描述的是一组差异很大的服务共同呈现的信号。","nextHeading":"照护不能停在症状量表","next":"暴力经历常与持续的安全威胁、经济压力、迁移和社会排斥交织。心理支持可以处理痛苦，却不能独自消除施暴风险或替代安全资源。作者提到研究中缺少亲历者参与，这不只是研究治理问题，也会影响项目是否真正回应当事人重视的目标。未来项目要与社区和幸存者共同设计，同时报告不良影响、转介、安全和生活功能；扩大覆盖面时，培训与督导不能因为“非专科交付”而被省略。"},"prenatal-digital-mindfulness":{"heading":"孕期改善没有自然延续到产后","text":"研究最值得记住的并非只有“六周项目有帮助”，还有这个时间上的转折：孕期失眠分数出现小幅改善，产后却没有看到同样的组间优势。怀孕阶段的压力、身体变化和作息与产后照护新生儿时并不相同，一段时间有效的练习不一定能自动迁移到另一个生活阶段。参与者自评也更接近她们主观经历，但容易受期待、回忆和填写习惯影响，不能等同于睡眠监测设备记录的变化。","nextHeading":"从一次课程转向连续支持","next":"如果效果在产后减弱，可能需要延长支持、设置复习环节，或为分娩后新的作息现实调整内容；这只是未来可检验的设计假设，不是本研究已经证明的治疗方案。项目还需要报告谁完成了课程、哪些练习真正被使用，以及症状变化对日间功能是否有意义。研究覆盖 160 人，比许多先导项目更大，但要推广到不同孕产服务和更复杂的临床人群，仍需更广样本和更完整的随访证据。"},"digital-behavioural-activation":{"heading":"“数字行为激活”不是一个单一产品","text":"综述纳入的形式从网络课程、电子提醒到远程治疗都可能不同。它们共享行为激活的核心思路：低落时人容易减少活动，而减少活动又会让生活中的积极反馈更少；治疗帮助逐步安排有意义且可完成的行动。数字媒介可以让练习更灵活，却也可能造成完成率差异。把多种交付方式放进同一总体估计，能回答整个领域的大致方向，不能直接告诉我们某个 App、某个课程或某种提醒设置有多大效果。","nextHeading":"症状之外，要问生活有没有变化","next":"作者考察生活质量、功能和压力，是因为抑郁量表下降并不一定代表重新工作、恢复关系或能处理日常事务。不同结局的证据可能强弱不一，读者应分别看，而不是把所有积极结果压成“数字治疗有效”。下一步研究要说明人们实际完成了哪些模块、是否有治疗师支持、谁中途退出，以及改善能否维持。若产品不断更新，研究结论还要对上具体版本，不能把旧试验结果自动移植到新工具。"},"digital-eight-disorders":{"heading":"把八类障碍放在一起，既有好处也有代价","text":"跨诊断汇总能帮助读者看到数字治疗研究版图，却容易让人误以为所有疾病都对同一种线上方式反应相同。抑郁、失眠、恐惧、焦虑、强迫和创伤相关问题在症状、治疗目标和风险上都不同；即便都使用数字平台，内容、疗程和人工支持也可能截然不同。荟萃综合按诊断分组并比较指导与否，是试图保留这些差异，但每个类别里的试验数和对照条件仍限制判断精度。","nextHeading":"指导与否，不能只看一个开关","next":"“有治疗师指导”可能包括定期反馈、简短提醒或完整远程治疗，研究间的定义并不统一。要回答指导是否增加疗效，需要比较可比项目，同时衡量投入时间、完成率和服务成本。这个综述更适合用来定位哪里已有研究、哪里仍稀少，而不是拿总体排行决定临床部署。实际选择应先确认具体障碍、患者需要、项目证据对应的人群及遇到风险时的人工支持方案。"},"cbt-sleep-psychosis":{"heading":"把 CBT-I 放进精神病服务，需要怎样调整","text":"标准失眠认知行为治疗有清晰的行为练习，但精神病性体验、药物副作用、日间嗜睡和生活环境都可能改变治疗节奏。综述不只问睡眠分数，也整理可接受性、退出和方案调整，这些实际细节关系到服务能否开展。纳入 14 项研究意味着证据开始累积，却还不足以证明存在一套统一、成熟的改编版本。尤其是小型或非随机研究，可能让积极体验更容易被发表或被观察到。","nextHeading":"可行性信号不是标准治疗指南","next":"如果患者愿意参与、退出不多，说明进一步试验有现实基础；这与确证疗效仍是两件事。未来研究应报告具体哪些模块被修改、治疗师如何处理精神病症状波动、与药物照护如何协同，并设置更长随访。临床团队可以把睡眠作为值得评估的共同目标，但不能仅凭这篇综述认定某个 CBT-I 版本适用于所有精神病患者。需要更可靠比较来确定获益、风险和最合适的支持强度。"},"ceta-ipv-hiv":{"heading":"症状改善不能替代安全与结构性支持","text":"CETA 试验的心理结局值得关注，因为参与者同时面对 PTSD、抑郁、亲密伴侣暴力和 HIV 照护压力。结果显示症状可以改善，但暴力和物质使用没有出现同样的组间差异。这提醒我们，心理治疗处理的是困扰的一部分；安全住所、法律支持、经济资源和医疗照护需要各自的服务回应。把症状变化解释成环境已经变安全，会对患者造成误导，也会把解决暴力的责任错误地推给受暴者。","nextHeading":"结果属于一群处境具体的参与者","next":"研究在南非 HIV 服务场景中实施，对象是有近期暴力经历且治疗依从困难的女性。主动对照组同样获得安全检查与安全计划，所以估计的是在这些支持之上增加 CETA 的差异，而不是“治疗”对“完全不管”。主要试验关注 HIV 结局，本文报告的抑郁和 PTSD 是次要结局。未来工作应让亲历者参与设计，持续监测安全风险，并分别报告心理、暴力和医疗结局。"},"social-determinants-prevention":{"heading":"组合方案有效，不代表我们知道哪一部分在起作用","text":"把心理预防与社会支持放在一起，回应了一个朴素问题：如果压力的一部分来自生活处境，单教个人应对够不够？31 项试验横跨 21 个国家、不同年龄与不同方案，合并后短期某些发生风险下降，提供了值得重视的平均信号。但组合里可能包含多种组件，不能据此判断现金支持、社区服务或心理课程分别贡献多少。焦虑发生率没有可用数据，正说明一个领域的大型证据汇总仍可能留下关键空白。","nextHeading":"别把“社会因素”写成一个万能项目","next":"低收入国家内部的服务、资源和生活环境差异很大；社会决定因素干预也不是一种标准化治疗。要决定如何实施，需要知道每种组件、成本、可持续性和参与者实际能否获得支持。较长期的结果主要集中在儿童抑郁症状，不宜把短期风险变化外推成长期普遍保护。未来研究可直接比较组合方案与单项方案，同时报告不同群体与焦虑等未充分测量结局。"}};
window.SOPHIA_BATCH_VIGNETTES={"star-ptsd-psychosis":"假设一位来访者既被创伤回忆反复打断，又仍在经历令自己害怕的声音或念头。照护团队可能很自然地想先处理眼前最明显的症状，可创伤本身也许正是痛苦的一部分。这个两难不是某位论文参与者的原话，而是帮助理解试验为何要检验“能否同时照顾两边”。\n\n治疗的难点不是简单决定“谈不谈创伤”，还包括如何共同设定步调、怎样回应症状波动，以及出现风险时谁来支持。假如一个研究只纳入症状已经稳定的人，答案未必适用于仍承受多重困扰的患者。于是这项试验重要的地方，是把临床常见的顾虑变成可以追踪的安全性和症状问题。","violence-nonspecialists":"一个刚搬到新地方的人，可能很需要有人听她说说经历，却离专科服务很远，或者不知道怎样预约。社区里受过训练的支持人员或许能成为第一道门，但暴力带来的安全、住房和经济难题不会因为一次谈话消失。这个场景是说明服务距离的假设例子，不代表综述中的某一位幸存者。\n\n“有人可以谈”是重要的一步，但还要看谈话之后能否持续跟进，是否有尊重当事人选择的安全计划，以及复杂需求能不能转给合适的服务。把支持交给非专科人员，重点不是降低专业标准，而是让服务更靠近人，同时保留培训、督导和清晰的升级路径。","prenatal-digital-mindfulness":"想象一个白天被工作和产检塞满的人，终于在夜里安静下来，却发现担忧反而更响。手机课程的吸引力，是能在家里、按自己的时间练习；真正的问题则是：几周后还会不会用，生活进入产后新阶段时，这些练习还能不能派上用场？\n\n怀孕和产后并不是同一种生活情境：身体感受、时间安排、照护责任和可休息的机会都可能改变。因此，课程结束时的改善只讲完了故事的一小段。研究把孕晚期与产后也纳入观察，等于继续追问：效果有没有留下来，还是环境变化后需要另一种支持？","digital-behavioural-activation":"低落的时候，人可能先取消一次散步，再推掉见朋友，日子慢慢只剩必须完成的事。行为激活的想法，是从小而可行的一步重新接触有意义的活动，而不是要求立刻振作。线上项目能否帮人迈出这一步，取决于课程内容、提醒和真人支持，而不只是它是不是一个应用。\n\n比如“重新出门”并不一定是去做一件宏大的事，也可能是把一项曾经在乎、现在做起来有点难的活动拆成更小的步骤。治疗关注的是行动与情绪之间的循环，而不是把低落归咎于不够努力。数字工具可以提供结构，却不能自动知道某项活动对这个人的意义。","digital-eight-disorders":"朋友把一个睡眠应用推荐给焦虑的同事，又把同一个应用发给有创伤经历的家人。名字都叫“数字心理干预”，实际目标和需要却可能完全不同。面对八种诊断，研究者必须把地图分区；读者也要记住，同在一张地图上，不代表路线可以互换。\n\n失眠项目可能训练睡眠节律，抑郁项目可能安排活动，创伤支持还要顾及安全和触发体验。即使形式同为手机课程，它们解决的问题也不一样。跨病种综述可以告诉我们研究版图的大致轮廓，但临床选择必须回到具体方案、纳入人群和结局，而不是只看一个“数字治疗总体有效”的标题。","cbt-sleep-psychosis":"一个人白天已经被声音和药物带来的困倦折腾，晚上又迟迟睡不着。给他一张通用睡眠建议单，未必回应了真正的困难；但直接照搬普通失眠治疗，也可能忽略他的体验和照护安排。这个假设例子呈现了适配的必要性，并非研究里的真实病例。\n\n对治疗者来说，调整不只是把材料换几个词：要弄清睡眠与症状、药物、白天活动和安全顾虑怎样交织，还要看每一步患者是否觉得可行。综述同时整理疗效和可接受性，正因为一个统计上可能有效的方案，如果人们无法坚持或感到不合适，也很难成为日常照护的一部分。","ceta-ipv-hiv":"当一个人同时面对伴侣暴力、情绪困扰和规律就医的压力，要求她“先专心处理心理问题”可能并不现实。照护如果能回应多个彼此牵连的困难，才更贴近生活；同时，安全和医疗支持也不能被心理治疗取代。此处是用于理解研究问题的假设情境，并非论文个案。\n\n整合式支持的吸引力在于减少“每个问题都要从头找一个服务”的负担；它的责任也更重：提供者要知道自己的能力边界，保护隐私，并能在风险出现时连接医疗、法律或安全资源。论文聚焦的特定女性群体让问题更具体，也提醒读者不要把结果随意推广到所有暴力经历者。","social-determinants-prevention":"如果一个社区的年轻人持续面对不稳定住房、收入压力或歧视，只教他们个人如何调节情绪，可能碰不到痛苦的重要来源。反过来，只改善环境也未必让每个人都能获得心理支持。研究者把两类预防措施放在一起，想知道同时行动会不会改变问题发生的风险。\n\n可以把它想成两条同时推进的路：一条给人应对压力的心理工具，另一条试图改变让压力持续存在的现实条件。组合起来可能更完整，也更难评估，因为不同项目处理的社会问题并不相同。理解综述结果时，要看它究竟测的是障碍新发、症状变化，还是生活条件改善，不能把这些结果混成一个笼统的“预防有效”。"};
window.SOPHIA_FIGURE_GUIDES={"sleep":{"title":"跟着图表读原文","intro":"这项交叉试验的图表按“实验怎样安排—睡眠有没有变化—脑电看见什么—醒来后如何”展开。原论文图和表可从全文链接打开。","items":[["图 1｜一夜实验怎样安排","先看时间轴：每位参与者有筛查夜、适应夜和三个实验夜；夜间两个时点分别给药。交叉设计意味着同一个人经历不同条件，减少人与人之间睡眠差异带来的干扰。","它能说明药物与测量的先后关系；不能把三个实验夜误当成三个独立患者组。"],["图 2｜睡眠阶段的箱线图","横向比较安慰剂、曲唑酮和 GHB 条件；纵向指标分别是 N1、N2、慢波睡眠、REM 的比例，以及入睡时间、夜间清醒和总睡眠时长。箱体表示中间一半数据，散点让人看到个体差异。","慢波睡眠比例变化不自动等于整夜睡眠更好；总睡眠时长和睡眠效率也要一起看。"],["图 3｜整夜脑电频谱","曲线按频率展示非快速眼动与 REM 睡眠中的脑电功率，底部标出经过多重比较校正后有差异的频率范围。它回答“脑电活动在哪些频段变了”，比单看睡眠阶段更细。","频谱差异是生理信号，不是患者感受，也不能单独证明情绪改善机制。"],["图 4｜一位参与者的睡眠结构示例","三行分别展示睡眠阶段随时间变化、频率—时间图和慢波活动轨迹。它很适合教人读图，但只展示一个人的夜晚。","个案式示意不能代表群体平均；群体结果仍看图 2、图 3 和结果表。"],["表 2｜醒来后发生了什么","把持续注意力、工作记忆、主观睡眠感、醒后困倦和情绪分开列出。读表时应逐个看指标与不确定范围，不能把多个结局压成一句“第二天状态更好”。","不同测试反映不同能力；短期实验室任务不等于真实生活中的工作表现。"]]},"mbct":{"title":"跟着图表读原文","intro":"这篇试验的图表分别回答：谁进入了试验、主要结论稳不稳、增加的课程是否值得服务资源。","items":[["图 1｜参与者流程图","从转介和资格筛查开始，沿箭头看谁被随机分组、接受课程、完成 10 周和 34 周评估。流程图还标出研究团队曾发现 25 人的自报资格与服务记录不一致，并在后续改用服务记录核验。","失访会让后续结果更不确定；不要只看最初随机的 234 人，也要看每个时间点实际有多少数据。"],["表 2–3｜连续分数与缓解比例","一张表呈现 PHQ-9 等连续量表的组间平均差，另一张呈现缓解等二分类结局。平均少几分和“达到缓解的人更多”是两种不同问题。","平均差不能说明每个人都改善；二分类比例也会受缓解阈值影响。"],["图 2｜敏感性分析森林图","每一行是对主要结果做的一种合理重算，例如补入缺失数据、考虑服务点差异或改变纳入规则；横线是 95% 置信区间，竖线代表没有组间差异。","若多种分析方向相近，结论较稳；它们仍共享同一批试验资料，不是独立重复试验。"],["图 3｜成本与健康收益","A 图把 10,000 次重抽样得到的成本与 QALY 差异画成点云；B 图显示在不同支付阈值下，MBCT 被判为成本效果较好的概率。","成本效果概率是群体与模型层面的决策信息，不是患者接受治疗后获益的概率。"]]},"pramipexole":{"title":"跟着图表读原文","intro":"重点看样本如何留下来、主要症状曲线何时分开，以及疗效之外的退出和副作用。","items":[["图 1｜PAX-D 试验流程","217 人参加筛查，151 人随机分组；图中继续追踪哪些人在第 12 周和第 48 周仍有数据。主要终点的数据人数少于随机人数，这是临床试验常见但必须留意的现实。","第 48 周只有部分人完成随访；长程观察不能与预先设定的第 12 周主要分析混为一谈。"],["图 2｜QIDS-SR16 症状随时间变化","纵轴是自评抑郁症状分数，横轴是治疗周数；两条均值曲线和阴影标准误显示平均变化及其精确度。虚线标明第 12 周主要终点。","曲线分开表示组平均变化，不意味着每名参与者都沿着均值轨迹改善。"],["表格与补充材料｜把获益和耐受性并排看","第 12 周反应率、缓解率和其他结局补充主要量表；不良事件及停药信息则告诉我们维持治疗的代价。","不能只引用症状差异而略去更多人因不良事件停止普拉克索这一点。"]]},"cosi":{"title":"跟着图表读原文","intro":"COSI 的图表把服务中的父母、随访轨迹、症状分布和安全事件放在一起；阴性结果需要和两组的变化轨迹一起读。","items":[["图 1｜谁进入了试验、谁完成随访","流程图追踪筛查、随机分组、接受 Circle of Security-Parenting 课程以及后续测量的人数。它能帮助判断结论建立在多少人的资料上。","若后续数据缺失，平均趋势的可信范围会变宽；退出原因也很重要。"],["图 2｜CORE-OM 分数分布和时间趋势","图中不仅比较两组的平均线，也展示每个时间点的分数分布。看两条线是否逐渐分开之前，先看分布重叠和变化幅度。","两组都随时间改善、但组间差异不显著，并不证明两种照护完全相同。"],["表 3–4｜主要与次要结局、不良事件","回归表列出主要心理困扰结局和其他结局的估计差异；安全表单列不良事件。把统计区间和事件数一起看，才知道“没有显著差异”覆盖哪些范围。","结果只对应在英格兰围产期服务中加入这套课程，不能外推到所有亲子或依恋干预。"]]},"ketamine":{"title":"跟着图表读原文","intro":"这篇机制研究先把药物输注与脑部测量对齐，再把脑内 Glx 信号与次日症状放在同一个人身上比较。","items":[["图 1｜实验时间轴和脑区定位","先看输注期间何时采集磁共振波谱，以及研究者在脑内选取的测量体积。时间安排决定了它观察的是输注早期变化，不是整个疗程。","磁共振波谱估计的是特定脑区的代谢物信号，不是直接拍到神经元如何“工作”。"],["图 2｜症状前后变化与个体连线","粗线代表组均值，细线把同一参与者给药前与次日的分数连起来；配对线能看见个体方向与平均趋势不完全一致。图中还分开呈现抑郁、快感缺失等量表。","次日变化是短期测量；不能替代更长随访或临床功能结局。"],["图 3｜波谱位置与信号拟合","图里展示 voxel（脑内采样体积）放在哪里、不同参与者位置重叠多少，以及仪器信号与数学拟合线如何对应。读者可以看到 Glx 是从复杂信号估算出来的。","拟合质量和参与者数据完整性会影响估计；这不是对脑内单一化学过程的直接测量。"],["图 4–5｜Glx/tNAA 在输注过程中的曲线","每个点是一个输注时间段相对基线的变化，分别画出安慰剂预处理和纳曲酮预处理；误差线表示标准误。按性别拆分的图属于探索性呈现。","样本中只有 24 人有合格波谱资料；分组后人数更小，不能据此确立性别差异或机制定论。"],["图 6｜不同访问顺序的临床变化","图中分开列出先安慰剂后纳曲酮、或先纳曲酮后安慰剂等顺序，帮助检查交叉试验是否受访问顺序影响。","多面板和多指标会增加偶然显著的机会；应以论文预设主要结局和统计方案为准。"]]},"dmt":{"title":"跟着图表读原文","intro":"IIa 期试验只有 34 人，图表的价值在于清楚展示阶段、随机组和随访，不是让小样本看起来像确证证据。","items":[["图 1｜两阶段给药设计","第一阶段双盲：17 人先接受 DMT，17 人接受安慰剂，双方都有支持性心理治疗；两周后进入开放阶段，原安慰剂组接受 DMT，原 DMT 组可接受第二次给药。","只有第一阶段保留随机安慰剂比较；开放阶段之后不能继续把两组当作盲态对照。"],["图 2｜399 人筛查后只随机 34 人","流程图显示从预筛、正式评估到随机的筛选漏斗，及两人退出、拒绝第二剂但仍完成随访的情况。","严格筛选提高了研究控制度，也意味着结果未必适用于未入选的广泛临床人群。"],["图 3｜MADRS 从基线到三个月","纵轴为抑郁严重度，横轴从基线延伸至 105 天；误差线是均值标准误。双盲阶段第两周出现组间差异，随后开放阶段两组都接受过 DMT。","早期显著差异不是长期随机对照证据；开放期保持改善不能排除期待、时间或其他因素。"],["表 2–3｜症状变化与治疗相关不良事件","症状表按量表与时间点列出变化；安全表列研究者判断与治疗相关的事件。一起读才能看到获益信号与治疗负担。","小样本难以发现低频风险；“未观察到”不能解释为“风险不存在”。"]]},"star-ptsd-psychosis":{"title":"跟着图表读原文","intro":"STAR 的主图最适合从流程图读到主要结局，再对照次要结局和安全性；不要让大量次要分析盖过预设主问题。","items":[["图 1｜305 人如何进入九个月治疗","流程图显示 154 人分到整合创伤治疗加常规照护，151 人分到常规照护；同时列出 4 个月、9 个月评估完成情况和实际治疗参与。","临床评估完成率与参与治疗人数不是同一概念；两者都决定结果如何解释。"],["图 2｜CAPS-5 的主要结果","按时间点比较 PTSD 临床访谈严重度；关注 4 个月中期与 9 个月主要终点的方向和差距。数值差异应和置信区间、缓解比例一起读。","主要结局支持创伤症状平均改善；它不说明所有精神病症状、功能和生活领域同时改善。"],["表格/次要结局｜哪些变化一起出现，哪些没有","研究还测量妄想、幻听、抑郁、焦虑、恢复感和社会功能。结果并非全部同方向；27 项次要结局没有多重比较校正。","次要结果可帮助描绘治疗可能影响的范围，但偶然阳性的风险高于预设主要结局。"],["安全性结果｜担心恶化是否发生","把严重不良事件、症状恶化和治疗脱落分开看。安全结论来自试验期间实际记录的事件和随访，不是对所有可能风险的保证。","试验支持在受训团队、监测和个体化方案下提供治疗；不等于无需评估即可普遍套用。"]]},"violence-nonspecialists":{"title":"跟着图表读原文","intro":"这篇综述把研究筛选、总体效应和异质性拆成几步。森林图里的横线往往比汇总菱形更能说明证据是否一致。","items":[["图 1｜研究筛选流程","从数据库检索数量一路追踪去重、全文评估、排除理由，到最后 45 项随机试验。这个漏斗说明“纳入多少”和“为什么排除”都可审查。","研究流程透明不代表纳入研究本身质量都高。"],["森林图｜四类结局的平均差异","每个方块是一项研究的效应估计，横线是其不确定区间；底部菱形是合并结果。抑郁、PTSD、焦虑和功能损害要分别读。","研究差异很大，且偏倚风险高；平均结果偏向干预不代表每种项目、暴力情境和地区都同样有效。"],["亚组/调节分析｜哪些条件可能改变效果","作者尝试比较宏观环境、服务场景、提供者特征、暴力类型和治疗类型。此类分析在回答“效果为何不同”，但各格数据量通常少于总体分析。","亚组趋势多用于提出后续假设；不能依据单个亚组直接给服务人员排名。"],["补充材料｜逐研究偏倚与稳健性","附录列出各研究质量判断、敏感性分析及数据可用性说明。遇到高异质性时，检查这些材料比只读摘要中的合并数更重要。","本文没有纳入亲历者参与研究；这限制了对干预可接受性和权力关系的理解。"]]},"prenatal-digital-mindfulness":{"title":"跟着图表读原文","intro":"试验把干预内容、参与者流失、症状变化和可能机制都画出来；图表能帮助分清“课程做了什么”和“结果怎样变化”。","items":[["表 1｜六周课程具体包含什么","按周列出微信小程序中的正念内容和练习主题。先看干预实际交付的成分，才能避免把结果泛化到任何冥想音频或手机应用。","课程组合了数字材料、练习和标准照护，不是单独测试一种抽象的“正念”。"],["图 1–2｜课程界面与受试者流程","界面截图说明参与者看到的工具；CONSORT 流程图则区分“某次没有完成评估”与“退出后续研究”。两者不是同一件事。","在线自评中短暂漏答并不等于永久退出，读流程图时应看定义。"],["表 3｜孕期与产后的结局变化","混合效应模型比较基线、干预后和约 42 天产后测量的失眠及其他结局。重点看时间点和置信区间：孕期有差异，不代表产后持续。","主要信息是孕期失眠自评改善，而产后组间差异不再显著。"],["图 3｜可能的作用路径","中介图将治疗分组、睡眠相关认知行为变化和失眠分数连接起来；星号表示统计显著，ns 表示未显著。","中介分析是机制线索；即使路径显著，也不能单凭它证明因果链已经确认。"]]},"digital-behavioural-activation":{"title":"跟着图表读原文","intro":"系统综述先展示如何筛出试验，再用森林图和偏倚表回答数字行为激活“对哪些结局、在何时”有信号。","items":[["图 1｜PRISMA 筛选流程","流程图显示从检索记录到纳入研究的数量变化，帮助读者看出筛选规模和排除环节。","不同研究报告不全会影响可纳入荟萃分析的结局数。"],["表 1–2｜项目差异","研究特征表和干预特征表比较国家、对象、数字平台、课程模块和支持方式。研究名称都叫“数字行为激活”，实际体验可能差很多。","不能把合并结果直接归给某个具体应用或单一交付方式。"],["图 2｜森林图按结局分面","抑郁、行为激活、生活质量和压力各有合并效应；方块、横线和菱形分别表示单项研究估计、不确定范围和总体结果。","显著结果出现在不同随访月份；抑郁 12 个月并未保持显著，不应把短期结果写成持续疗效。"],["图 3｜偏倚风险汇总","按研究逐项检查随机、失访、测量和选择性报告等问题。颜色/符号不是“研究好坏总分”，而是不同偏差来源的判断。","系统综述能把证据整理起来，但无法修复原始试验的局限。"]]},"digital-eight-disorders":{"title":"跟着图表读原文","intro":"这项跨诊断综述最重要的读图习惯，是逐病种看森林图，再看研究分布和调节分析，不能只盯总体合并效应。","items":[["表 1｜纳入研究的设计差异","研究特征表呈现 168 项研究的干预、比较对象和人群，显示不同诊断的证据底盘并不均匀。","总样本大不代表每种诊断都拥有同样多、同样可靠的试验。"],["图 1｜试验来自哪些国家","地图/计数图按国家展示试验数量。它显示证据从哪里来，也让研究代表性和资源分布一目了然。","试验数量多的地区不等于人群更需要干预；地图也不说明当地服务可及性。"],["图 2｜八种障碍的合并效应","每一行或每个面板对应一种诊断；横轴是标准化平均差异，零线代表无组间平均差。对照类型不同，效应大小可能变化。","不能把跨病种总效应读成八种障碍都得到同等支持；个别病种的精确度和偏倚风险差异很大。"],["图 3–4｜调节分析","回归分析探索指导支持、对照类型等研究特征是否伴随效应改变。斜率表示研究层级的关联，不是患者个人层级的预测。","跨研究调节可能受其他未测因素影响，主要用于提出解释，而不是证明哪种组件造成疗效。"]]},"cbt-sleep-psychosis":{"title":"跟着表格读原文","intro":"这篇系统综述主要通过表格而非单张结果图呈现证据。读表时要先分清随机对照研究和无对照前后比较。","items":[["表 2｜14 项研究分别研究了谁","表格对照国家、样本、精神病风险/诊断、睡眠问题和研究设计；其中只有一部分是随机对照试验。","不同研究人群差异较大，不能把它们视作同一种患者。"],["表 3–4｜治疗调整与偏倚风险","表 3 对比治疗格式、是否省略睡眠限制、是否处理幻觉/妄想、害怕上床或噩梦等适配；表 4 再评估随机和非随机研究的偏倚风险。","不同组合和质量意味着“CBT-I”并非纳入研究中的同一种治疗，效果也不能脱离偏倚风险看。"],["表 5–7｜睡眠、精神病及其他结局","每行是一项研究，列出治疗后和随访效应。受控研究报告组间 Cohen’s d，无对照研究报告前后方向；作者统一符号，让正值表示相对改善。","不能把无对照的前后变化和随机组间效应当成同等级证据；区间宽、偏倚高的研究需要更谨慎。"],["表 8–9｜可接受性、退出与不良事件","质性主题整理参与者怎样体验治疗；另一张表列退出和不良事件。疗效和“能否接受、能否继续”是两条互补证据。","14 项研究给出初步支持，但不足以确定一个适用于所有精神病患者的标准改编版 CBT-I。"]]},"ceta-ipv-hiv":{"title":"跟着表格读原文","intro":"这篇随机试验的次要结局分析没有复杂主图，关键证据集中在全样本、完成治疗者和高基线症状亚组的对照表。","items":[["表 1｜399 位参与者起点是否相近","基线表按随机组比较人口特征、暴力经历、HIV 治疗情况和心理症状。随机分组不保证每项都完全相同，但可检视明显不平衡。","基线表描述的是群体起点，不代表任何个体的病情。"],["表 2｜全样本的抑郁与 PTSD 变化","查看估计均值差、临床效应量及不同随访时点，了解全体随机参与者中次要心理结局的组间变化。","本文分析的是次要结局；不要把它误说成原试验所有主要目标都改善。"],["表 3｜完成治疗者分析","只分析完成 CETA 的参与者可了解依从治疗者中的变化，但会失去随机分组保护，完成者可能本来就不同。","不能用完成者结果取代随机全样本结果；完成者可能本来就更容易参与或改善。"],["表 4｜高基线症状亚组","作者探索起始症状较高的一半人是否有不同变化。亚组效应需要与预设方案、人数和区间一起读。","亚组信号属探索性质，不能据此作个体治疗选择或断言严重者更适合。"]]},"social-determinants-prevention":{"title":"跟着图表读原文","intro":"综述把“心理预防”和“改善社会处境”组合起来研究，图表分别展示研究筛选、短期发生率和量表症状随时间的证据。","items":[["图 1｜PRISMA 文献筛选","显示从检索到最终纳入 31 项随机试验的路径；全文排除理由能解释哪些研究不符合预先设定标准。","系统搜索覆盖面广，但纳入研究质量仍需逐项判断。"],["图 2｜短期抑郁或 PTSD 新发","森林图呈现干预后新发病例的相对风险；每项研究横线是区间，汇总菱形是合并结果。这里测的是是否新发，不是症状分数。","风险下降不等于每个人都不会发病；焦虑发生结局没有足够可用数据。"],["表 2｜不同随访时间点的合并结果","表格把干预后、较短随访和更长期随访拆开，按抑郁、PTSD 等结局呈现。短期发生率与长期症状变化不可互换。","长期信号主要限于儿童抑郁症状；不能概括成所有组合干预长期有效。"],["附录｜干预到底如何组合","补充表说明哪些项目提供心理技能、哪些同时涉及教育、经济或社会资源支持。不同组合之间的差异，是异质性的来源之一。","综述没有识别出一个已经确证、可原样复制的统一方案。"]]}};
window.SOPHIA_PAPER_WALKTHROUGHS={"sleep":{"title":"再沿着论文往里读一步","sections":[["为什么盯着慢波睡眠？","睡眠研究常把“睡得好不好”拆成不同问题：能不能睡着、夜里会不会醒、深睡眠占多少、早上是否清醒。慢波睡眠是脑电定义的 N3 阶段，与主观睡得香并非一回事。研究者选它作为可以在实验室操控的生理目标，再观察注意力、记忆和情绪是否一起变化。这样设计能验证“生理指标可被改变”，但患者最关心的症状改善还需要另一个临床试验来回答。"],["交叉设计为什么有用？","同一个人先后经历不同夜晚，比把小样本硬分成几组更能减少个体睡眠差异的影响。第一晚筛查，第二晚适应实验室，之后的三个实验夜才进入条件比较。药物安排在夜里不同时间，研究团队还要留出间隔，以免前一晚影响后一次。读结果时要记住，交叉设计的优势是让每个人作自己的参照；它不等于长期连续服药，也不代表日常卧室里的睡眠会一样。"],["测量很多，答案也要拆开看","多导睡眠监测记录睡眠阶段、醒后时间和脑电频谱；次日再做持续注意力、工作记忆和主观问卷。设备指标和体验指标可以相互补充，却不能互相替代。论文同时比较了多个频段、睡眠阶段和次日结局，因此读图时要留意预先设定的分析和多重比较校正。一个频段出现差异，不足以说明整体睡眠或抑郁症状已改善。"],["这项实验没有追踪的东西","实验只观察短期、受控的给药夜晚与次日表现，没有检验重复使用、长期安全、生活功能或抑郁症状疗效。即使某种药让 N3 增加，也不能据此推断它适合治疗抑郁；其他睡眠阶段、夜间醒来和次日困倦都需要一起评估。论文的重要贡献是让机制问题变得可测量，而不是把一种睡眠药物变成治疗建议。"],["把实验夜的数字拆开看","这项研究以健康成人为对象，在不同夜晚比较安慰剂、羟丁酸钠和曲唑酮，并将药物安排在夜间不同时间。图表中睡眠分期和脑电频谱的变化不是同一件事：分期比例告诉我们整夜结构如何变化，频谱则反映特定脑电频带的相对功率。作者还测量次日注意力、工作记忆与主观状态；若一个指标变化而另一个没有同步变化，不能只挑最显著的结果讲成“睡眠整体改善”。"],["为什么结果不能直接变成治疗建议","小样本实验有能力发现受控条件下的生理信号，却没有足够规模去比较罕见不良事件、不同患者亚型或临床重要的长期结局。受试者知道自己可能感受到药物，也可能影响主观问卷。研究的价值在于提出后续假说：怎样改变慢波睡眠才不会损害其他阶段或第二天功能？回答这个问题还需要在失眠或抑郁患者中进行更长时间、以患者获益为终点的试验。"],["曲唑酮和羟丁酸钠的比较在问不同问题","论文不只是检验一种药能否“增加深睡”。研究安排也让作者观察，药物在前半夜或后半夜给药时，慢波睡眠与 REM 睡眠、觉醒和第二日认知是否呈现不同组合。羟丁酸钠和曲唑酮作用途径不同，研究比较的是受控实验下的睡眠生理效应，不是临床常用药物之间的总体疗效、安全性排名。不能据此建议患者自行换药或调整服药时间。"],["从脑电变化到记忆任务，中间隔着多层解释","论文把生理记录与次日注意任务、工作记忆和主观感受并列，目的是检查睡眠结构改变有没有对应的白天表现。读图时要先确认每个结局的方向：任务反应更快不必然意味着准确率更高；主观清醒感也不等于客观注意稳定。多项任务若有些显著、有些没有，应该按预设主要结局和校正后的分析来判断，而不是将单一结果概括成认知增强。"],["研究对象和实验条件限制了外推","参与者是健康成人，而不是因失眠、抑郁或其他精神科诊断来求医的人。实验室夜间监测可精确记录脑电，但周围环境、睡眠机会和药物使用都比日常生活受控。健康志愿者短期出现的睡眠结构变化，不能直接预测临床患者会不会睡得更舒服、白天更有功能；也不能替代患者对困倦、跌倒风险和共病用药的评估。"],["这篇研究最稳妥的收获是一张研究路线图","论文把慢波睡眠作为可操控的中间指标，尝试连接药物、夜间生理和次日功能。读者可以从结果中带走“这些环节可以在实验里被同时测量”，而不是“改变其中一个指标就能治好情绪问题”。更完整的后续路线需要纳入有临床症状的人、选择患者在意的主要终点，并追踪多夜使用后的睡眠、白天表现和安全。"]]},"mbct":{"title":"再沿着论文往里读一步","sections":[["研究放在治疗路径的哪一站？","参与者不是刚开始治疗的人，而是已经在 NHS Talking Therapies 中接受至少 12 次高强度心理治疗、仍未达到研究缓解标准的人。234 人来自 20 个服务点，被随机分到追加 MBCT 或继续常规照护。这个入组条件决定了结论对应“首轮治疗之后的下一步”，不代表 MBCT 对所有抑郁患者都是首选。"],["追加的到底是一套什么课程？","干预包括一次个别介绍、之后八周团体课程，采用远程方式开展；对照组仍继续原有服务。这一点很容易被简化成“正念练习对什么都不做”，但试验实际比较的是一套有结构、带领和练习安排的课程，与现实服务中的常规照护。把效果外推到零散使用冥想软件或自学材料，需要另外的证据。"],["为什么把第 34 周放在核心位置？","研究在较早随访和 34 周都收集资料，主要临床结局是 34 周 PHQ-9。九项自评题能提供同一把尺子比较症状变化，但不能完整覆盖功能、关系、复工或个人对康复的定义。论文另报告缓解等分类结局和生活质量/资源使用，因此平均少 2.49 分、缓解比例、以及经济学判断需要分别读，不能互相代替。"],["稳健性分析和成本图在回答什么？","敏感性分析用不同合理假设重新估计主要结局，例如处理缺失数据、考虑服务点差异或调整样本定义，检查结果是否依赖单一分析选择。成本效果部分则把健康收益与服务资源放在一起，并用 QALY 和支付阈值做模型比较。模型概率是卫生服务决策工具，不是个人接受治疗后的成功概率；经济结论也依赖英国服务成本和阈值。"],["结果之外，流程图和补充分析告诉了什么","看参与者流程图时，应沿着筛查、随机分组、开始课程、完成随访一路数下去。研究在筛查阶段发现有些参与者自报的既往治疗次数与服务记录不一致，因此进一步核对资格；这是重要的质量控制，也说明临床试验里的“符合条件”需要操作定义。论文还报告缓解结局、生活质量和服务使用，能补充平均 PHQ-9 分数，但不能取代主要终点。"],["把统计差异翻译成一个人的经历","组间平均低 2.49 分说明随机分组后的两群人平均走势不同；它无法告诉我们每个人是否都改善、改善从哪一天开始，或是否恢复工作与关系。响应和缓解阈值会把连续变化变成“达到/未达到”的类别，临床上直观，但结果会受阈值设定影响。与其只问显著不显著，不如同时看置信区间、达到缓解的人数、缺失资料处理和患者重视的功能变化。"],["疗效结果怎样穿过随访时间","试验除 34 周主要临床结局外，还在课程后较早时点及之后追踪症状，帮助读者区分课程期间出现的变化与稍后是否维持。应比较不同时间点估计值和置信区间，而不只是看每条曲线是否继续向下。随访越久，可用资料通常越少，失访者的结局可能与留在研究中的人不同；统计模型能利用已有资料，但不能凭空恢复没有测到的体验。"],["经济学表格不是给患者的价格标签","健康经济分析把服务资源、患者生活质量和后续医疗使用组合进模型，估算在一定决策阈值下追加课程是否值得投入。表格中的成本、QALY 和增量成本效果比都依赖英国 NHS 的服务价格、观察期限及缺失数据假设。模型更适合帮助服务部门比较预算选择，无法替某位患者判断课程的个人价值，也不能推导出别国实施时会得到相同结论。"],["统计分析如何处理多地点和未完成随访","研究由多个服务点共同开展，参与者来自不同团队，分析需要考虑服务点差异，并尽量利用随机分组后收集到的随访资料。主要终点的结果应与论文的敏感性分析一起看：如果对缺失资料的合理处理、协变量调整或分析人群选择改变后方向仍接近，结论就不太依赖某一种做法。反过来，稳健性并不能消除失访者与留存者不同这一潜在偏差。"],["缓解、生活质量和安全结果如何补充主要发现","PHQ-9 的连续分数是主要症状结果；缓解率把变化转成是否达到预设临床范围，生活质量测量则尝试描绘健康状态和功能。安全结果关注试验期间发生的严重事件。它们不能相互替代：平均分有差异不保证多数人缓解，经济模型中的生活质量也不是完整的个人康复叙事。把这些结果并排，才能看到追加课程可能带来的收益、资源需求与未回答的问题。"]]},"pramipexole":{"title":"再沿着论文往里读一步","sections":[["“难治”在这篇研究里有具体门槛","试验针对单相重性抑郁中既往治疗反应不足的人，研究团队在筛查和导入期确认资格后，151 人进入随机分组。两组都继续原有抗抑郁治疗，差别是加用普拉克索还是安慰剂。因而这不是停掉既有治疗后单独试用普拉克索，也不是与其他增效药直接比赛。"],["从剂量上升到主要终点","普拉克索需要逐步调整剂量，参与者与评估人员保持盲法；研究预设第 12 周自评抑郁症状变化为主要终点，部分招募较早的人可继续观察至 48 周。论文中“计划观察 48 周”和“主要结论发生在 12 周”是两件事：较长追踪提供耐受与持续性的线索，但后续人数减少，估计不如主要终点稳定。"],["疗效不是只看平均分","主要量表平均差之外，作者还报告达到预设反应或缓解标准的人数，以及功能、快感缺失和安全性等结果。平均下降说明组水平变化，反应率/缓解率则告诉我们达到特定阈值的比例。读者还要看失访如何处理、各周实际有多少数据，避免把图上的平滑均值误认为所有人的个人轨迹。"],["治疗负担必须和收益一起讲","普拉克索组因不良事件停药比例高于安慰剂组，提示药物带来的平均症状收益伴随更难坚持的可能。研究样本约 150 人，也不足以识别罕见风险；更没有直接比较现有增效方案。把它读成“可讨论的候选策略”比读成“新标准”准确。论文更正记录也应和原始报告一起查看。"],["把均值、反应率和长期追踪放在一张桌上","主要分析显示第 12 周平均 QIDS-SR16 差异约 3.91 分；反应率和缓解率则把患者按预设改善幅度分类。这几种结果回答不同问题：均值利用每个人的分数变化，比例更接近“多少人达到一个门槛”，但门槛附近的细微差异可能令分类变化。到 48 周仍被观察到的参与者已经减少，所以长期曲线要同时读随访人数与不确定区间。"],["安全表不是药物风险的完整清单","试验里常见不良反应、严重事件、停药原因和自杀相关情况各有不同定义，不能只用一个“总体副作用率”概括。双盲设计有助于控制期待，但明显的恶心或嗜睡也可能让人猜到分组。PAX-D 的安全资料适合与症状收益一起用于临床讨论；约 150 人的规模无法排除低频但重要的风险，也没有足够力量确定哪类人最能耐受。"],["把“反应”与“缓解”分开讲，才能理解绝对获益","论文报告的反应标准与缓解标准并不相同：一个关注相对基线改善到一定幅度，另一个要求最终症状低到特定范围。两者人数都可以帮助理解平均差异，但比例应连同分母、失访处理和置信区间阅读。若一组平均分下降，仍可能有人没有变化、有人恶化，也有人改善很多；组平均值不是每一位参与者的故事。"],["剂量调整与盲法如何影响耐受性","普拉克索逐步加量，能否到达目标剂量、因不良反应停下或需要减量，都会影响“分配治疗”的平均结果。双盲有助于降低主观评分受期待影响，但药理反应可能让参与者猜到分组。论文中的耐受资料因此不只是安全附录，也是理解疗效在现实中能否兑现的一部分。临床使用时的监测、合并用药与患者偏好不由试验平均值替代。"],["研究流程里的导入期和随机分组很关键","筛查之后，研究设有一段导入与资格确认流程，随机分组前会再次核实入组条件。流程图中“筛查”“开始试验治疗”“进入主要分析”是不同的人数节点；不能把最初联系研究的人数当成疗效分析样本。随机阶段保留的参与者更符合方案设定的人群，但结果也因此不能直接代表所有在门诊被称作治疗抵抗的患者。"],["第12周以后的曲线应读成补充信息","研究计划较长随访，可以了解症状是否维持、治疗是否继续及后续风险；但主要终点后退出会让可用样本不断缩小。若后期均值仍有差异，需看置信区间和各时点的观测人数，并确认分析是否仍按随机分组。不能把一条延伸到48周的图线误读成每位参与者持续治疗并获得同样效果。长期结果的主要价值，是指出需要怎样的大型维持研究。"]]},"cosi":{"title":"再沿着论文往里读一步","sections":[["问题从真实服务里长出来","围产期心理服务接触到的父母，可能同时面对情绪困扰、照护压力和亲子关系担忧。Circle of Security-Parenting 课程的理论目标是帮助照护者理解婴幼儿的依恋需要；COSI 试验问的是，在已经存在的英格兰社区服务上增加十次团体课程，是否带来额外的平均获益。不是在问依恋是否重要。"],["理解“常规照护”是解读阴性结果的关键","371 位生育父母被分到常规照护加课程，或常规照护单独一组。常规照护并非空白对照，参与者仍可获得当地围产期心理服务。课程在真实服务环境内交付，这让试验更接近日常实施，但服务点之间照护内容也可能不同。若只看“干预组没有显著更好”，会漏掉两组都可能在接受帮助的事实。"],["主要结局和亲子结局不是一回事","主要心理困扰指标 CORE-OM 在不同时间点重复测量，论文也观察父母—婴儿关系、其他心理结果、课程参与和安全事件。图里的均值线展示群体走向，分布则显示参与者差异。若两组都随时间改善但曲线未明显分开，结论是没有检测到清楚的额外组间收益，不是证明课程对任何个体都毫无帮助。"],["实用性试验如何影响结论范围","随机设计降低了已测和未测基线差异对组间比较的影响，但课程实际参加程度、不同服务点的照护和后续失访仍会影响精确度。作者的结果针对特定课程版本、团体方式和英国服务体系；不能推到个别依恋治疗、其他父母支持项目或完全不同的医疗环境。阴性结果帮助服务评估新增课程的机会成本。"],["读懂基线表、课程参与和随访表","基线表是检查随机分组后两组起点是否大致可比，不是用来挑选“看起来差异最小”的变量重新解释结果。参与表告诉我们课程实际到课情况，随访表则显示各时间点有多少人提供资料。两者合起来可解释为什么理想课程效果与现实服务效果可能不同。研究中平均到课不足十次，说明“被分配到课程”与“完整接受课程”并不相同。"],["没有显著差异，置信区间仍然重要","主要结局的置信区间跨过零，意味着数据与略微有利于课程、略微有利于常规照护以及几乎无差异等可能性都相容。它不是证明两种照护完全等价；要证明等效需要预设临床可接受范围并为此设计研究。多项次要结局中偶尔出现的差异也需结合预先设定、时间点和多重检验来解释，而不能挑出一个数字代表整个试验。"],["亲子联结和儿童指标各自能说明什么","研究还测量父母对亲子联结的感受、照护行为、情绪调节与婴儿发展等结果。它们捕捉的是不同层面：父母报告的联结体验不等于观察员对互动行为的评分，婴儿发展量表也不能替代长期依恋结局。表格里若某个时间点出现组间差异，要同时看测量方式、随访时间、其他相关指标是否同向，以及研究是否为这项分析提供足够统计把握。"],["课程参与本身也是实施证据","平均到课次数低于完整十次，提示许多家庭很难按方案完成课程。照护婴儿、交通或线上接入、心理症状以及服务安排，都可能成为参与门槛；这些是现实世界干预效果的一部分。随机试验主要估计“被提供这套服务”的平均结果，而不是仅挑完成者计算课程效果。若只看完成者，可能把更有资源、更容易坚持的人当成所有父母。"],["按服务点观察能看到什么、不能证明什么","多地点试验让结果不只来自一位带领者或一家机构。不同服务点的招募、照护资源和课程经验可能有差异，因此作者检查实施情况与结果的变化。但每个点参与人数有限，某个点看起来更好不等于该地服务本身造成差异；这类比较通常需要谨慎，不能用来评判单个治疗师或机构。它能提示未来实施研究要记录培训、支持和参与障碍。"],["怎样把阴性主结果说得既诚实又有用","主要比较没有发现 COS-P 在 CORE-OM 上的明确额外改善；多数亲子和婴儿结局也未显示稳定差异。对服务决策而言，这意味着不能仅凭课程理念或某个次要结果就假设增加十次课程一定值得。它不否定亲子关系的重要性，也不排除其他有针对性、更高强度或不同交付方式的支持；而是要求新项目证明自己相对已有服务带来的额外价值，并报告谁能真正参与。"]]},"ketamine":{"title":"再沿着论文往里读一步","sections":[["先理解药物机制问题的两层假设","氯胺酮可能快速改变谷氨酸相关活动；研究团队又关注阿片受体系统是否参与这一变化。纳曲酮用于暂时阻断阿片受体，因此比较不同预处理条件下脑内 Glx/tNAA 信号与次日症状变化。如果两者同步减弱，会增加某条机制路径的可信度，但仍不是直接证明完整因果链。"],["一个人做两种条件，留下什么优势和风险？","26 名完成者在随机交叉安排中经历氯胺酮加不同预处理条件；两次访问之间安排间隔，降低前一次的影响。研究在输注前以及最初 30 分钟连续采集波谱，之后在次日测量抑郁和快感缺失等结局。交叉安排减少个体差异，但样本小、条件可被察觉、顺序效应仍值得检查。"],["脑内信号和患者症状来自不同测量层面","Glx/tNAA 是磁共振波谱对脑区化学信号的估计比值，不是直接数出某种神经递质释放了多少。症状量表则由临床评定或自评得到。论文在 24 位质量合格的波谱资料中看到条件相关差异，同时观察临床变化；两类结果相互支持一条假说，但不能把波谱变化当作疗效本身。"],["为什么小样本机制研究尤其要看图的细节","图中除了平均线，还呈现个体连线、访问顺序和时间段；这些信息能揭示均值背后的分散程度与潜在顺序影响。多个临床量表、时间点和性别拆分分析增加偶然发现的可能。作者的结果适合指导后续更大样本、预注册的机制试验，不适合用来决定是否合用纳曲酮或如何安排临床治疗。"],["主结果图里两种曲线不是两个独立组","交叉试验的图通常把同一人的两次条件连接起来。读者应同时看个体连线与组均值：若少数参与者变化很大，平均线可能被带动；若顺序不同的人走向不同，也可能提示残留或顺序影响。论文用时间序列展示输注前后波谱变化，再把症状量表放在另一个结局面板。两个面板分别回答生物信号与临床症状问题，不能把一条曲线当作另一条的直接替代。"],["把“阻断实验”理解成一段有限的因果链","纳曲酮是实验上操纵阿片受体的一种办法；若预处理后氯胺酮相关变化变小，会支持阿片系统参与，但仍取决于纳曲酮在该条件下是否只影响目标通路。论文还没有证明波谱变化是症状变化的中介，也未覆盖氯胺酮的其他作用机制。下一步可用更充分的对照条件、独立复制和预先指定中介分析来检验这条链，而不是把“参与”升级成“唯一原因”。"],["临床量表的分歧不是可以藏起来的噪声","研究同时报告由评估者完成的 MADRS 与患者自评等结局。若访谈量表呈现条件差异，而自评量表未达到显著，正确读法是不同测量提供了不同强度的证据，而非挑一个支持机制的数字。访谈和自评各有价值，也受评估时间、期待和症状维度影响。样本很小时，估计不精确；“未显著”不能证明完全没有差异，“一项显著”也不足以让所有结局都显著。"],["哪些后续实验能把机制故事讲得更完整","接下来需要更大样本、预先登记主要假设，并确认成像信号重复性。若要判断谷氨酸变化是否连接了受体阻断与症状变化，应有足够统计能力测试时间顺序和中介路径；若要判断纳曲酮自身影响，则需加入能识别它单独作用的对照条件。独立团队重复结果、延长随访并纳入更广泛患者，会比继续从同一小样本寻找亚组更能增强结论。"],["扫描质量和样本数在波谱研究中格外重要","论文最终有可用的波谱资料者少于完成临床评估者，因为扫描信号需要经过质量筛查。排除运动伪影和信号质量不佳有助于减少错误测量，但也会进一步降低样本量。图中的每个误差范围因此都应结合实际 n 值阅读；不要默认 MRI 图与临床量表使用的是完全相同的一群人。若可用扫描者与未能扫描者系统不同，还会影响结果代表性。"],["把相关图读成“伴随变化”，而非治疗机制已闭环","作者考察个体层面上波谱变化和症状变化是否相关。散点图里一条回归线只概括平均关系，点的离散程度能显示这种关系是否一致；相关显著也不表示脑信号先于并导致症状改善。若样本少、多个时间点都尝试相关分析，偶然模式更容易出现。最好的读法是它有没有帮助提出下一步可检验的机制问题，而非把图当作因果链的证据。"]]},"dmt":{"title":"再沿着论文往里读一步","sections":[["从 399 人到 34 人，筛选本身就是结果背景","预筛人数很多，最终只有 34 名中重度抑郁成人进入随机试验，说明研究条件相当严格。小样本有利于在早期阶段仔细监测，但入组者与普通门诊人群可能差别很大。两组各 17 人，任何一个人的变化都会对平均值造成较大影响，置信区间因此必须认真看。"],["治疗包含药物，也包含支持性心理治疗","参与者接受单次静脉 DMT 或安慰剂，同时有支持性心理治疗和研究团队监测。药物体验、治疗环境、准备与支持共同构成方案。试验不能把整体效果归因于单独药物分子，也不支持脱离临床团队自行尝试。文章标题里的“短效”描述药物体验时间，不等于抑郁疗效已经确证或风险较低。"],["双盲阶段与开放阶段要分开读","最初两周是随机安慰剂对照，主要比较发生在这一阶段；之后原安慰剂组也接受 DMT，研究进入开放标签追踪。开放阶段中两组分数继续改善，可以观察持续性和安全性，却失去了原先的随机对照，因此不宜把三个月的改善都说成持续的因果疗效。"],["图表里要找的不只是显著性星号","MADRS 曲线呈现组均值和误差范围；还需看基线、两周差异、随访人数和二次给药后的设计变化。安全表列出治疗相关不良事件，但每组仅十几人，无法排除罕见风险。IIa 期研究的任务是初步确认信号和可行性，后续大样本确证试验才更适合回答真实效果、持久性和风险。"],["试验流程图为什么值得仔细读","从 399 人完成预筛到 34 人随机入组，筛除原因包括诊断与安全条件不符、既往治疗史或其他排除标准。流程图因此说明结果适用人群是如何被选出来的，而不仅是招募困难的记录。两组人数相同不表示每个随访时间点都有完整数据；读后续曲线还要核对各阶段实际评估人数和退出原因。"],["“盲法成功”也需要结合主观体验理解","DMT 的体验可能很明显，参与者和临床团队即使被告知不知道分组，也可能凭主观感受猜测接受了什么。对照输注和支持流程可以改善比较，但难以保证主观期待完全相同。作者还测量了体验强度等变量；这类探索性关联既可能提示未来研究要记录什么，也可能受期待、症状和体验共同影响，不能当成剂量反应证据。"],["主要结果之外，功能和持续时间还没有完全回答","两周的 MADRS 变化是主要比较，研究还报告其他症状量表、体验和随访结局。对患者而言，症状分数下降与恢复工作、关系或日常功能并非同义；需要查看功能指标是否测量、是否出现相同方向和维持多久。开放阶段提供了一段观察窗口，但两组后续都接触 DMT，不能继续回答“若没有 DMT，同一时间会怎样”。"],["安全结果应按发生时间和严重程度阅读","论文将急性输注中的体验、治疗期间不良事件、严重不良事件分开报告。短暂的焦虑或恶心与住院等严重事件不是同一个层级；图表和表格中的发生人数也受每组样本只有十几人的限制。安全性依赖筛选、现场监测、治疗人员支持和退出后的随访，不能把“未发现相关严重事件”读作“没有风险”。更大试验要同时扩大样本并统一记录体验和风险。"],["为什么严格筛选既提升安全也缩窄代表性","排除某些精神病性障碍家族史、严重共病或特定近期物质使用，能减少早期试验中的风险和解释混杂；与此同时，临床中恰恰有不少人具有复杂共病。流程图每一步筛选都在定义最终证据适用的范围。后续研究需要逐步考察更多真实患者，而不是把早期入组标准隐去后，直接宣传结果适用于所有抑郁症患者。"],["治疗方案里心理支持为何不能从故事中删掉","给药前准备、输注现场陪伴、结束后的整合支持构成研究体验的一部分。团队、环境和患者预期可能影响安全感与主观报告；而试验没有把“药物”与“支持”做成完整的析因比较，所以不能算出两部分各自贡献多少。复制研究时应详细描述支持内容和人员训练，这样读者才能判断新试验检验的是相似方案，还是只保留了一个药名。"]]},"star-ptsd-psychosis":{"title":"再沿着论文往里读一步","sections":[["这群患者过去为什么容易被研究排除？","PTSD 和精神病症状可能同时存在，临床团队有时担心触碰创伤记忆会加重幻听、妄想或危机风险。STAR 并没有假设所有患者都适合同一方案，而是在英国二级照护中招募有两类诊断且仍有困扰症状的成人，检验受训团队能否在常规照护旁提供个体化治疗。"],["治疗是整合式的，不是把两套手册叠起来","治疗师把创伤聚焦成分放进精神病认知行为治疗框架，依据个体的创伤经历、当前症状和安全需求制定治疗路径；疗程可延伸至九个月。对照组仍接受常规照护。研究也记录治疗参与和剂量，因此疗效结果应与可接受性一起读，而不只是看分到治疗组的人数。"],["为什么把九个月 PTSD 症状定为主要结局？","CAPS-5 是临床人员访谈评估 PTSD 严重度，主要终点在九个月，四个月是中期评估。两组在基线后一路随访，线条随时间的变化帮助判断何时差异出现。约 8.67 分的平均差和缓解比例提供不同视角；主要结局比众多次要结果更适合承载核心结论。"],["次要结果的完整图景比“治疗改善所有症状”复杂","论文同时测量妄想、幻听、抑郁、焦虑、恢复感、功能和安全事件。部分次要结局方向有利，部分没有明显差异；27 项次要检验未作多重比较校正，偶然显著可能性更高。治疗组大多数人能够开始并达到最低剂量，说明方案可被许多人接受，但九个月长疗程需要专业训练和资源。"],["四个月和九个月的时间线不能压成一个结果","CAPS-5 在不同随访点重复评估创伤后应激严重度。四个月结果可帮助观察治疗过程中是否已有变化，九个月是预设主要终点；应优先把后者作为论文核心，再用早期测量理解变化轨迹。每个时间点的完成评估人数也可能不同。统计模型能处理一部分不完整观测，但前提假设仍需结合退出原因判断。"],["积极结果为什么仍需要接受者与服务条件","治疗组的大多数人开始了治疗，且多数达到最低剂量，是可接受性的重要迹象；但这不代表每个人都完成九个月疗程，也不代表各地都有足够受训治疗师。论文所称“整合”依赖治疗师将创伤工作与 CBTp 结合，并持续考虑安全。复制时若缺少训练、督导和个体化，不能假设同样结果自然出现。"]]},"violence-nonspecialists":{"title":"再沿着论文往里读一步","sections":[["“非专科人员”在这篇论文里如何定义？","作者指没有临床心理或精神医学正规教育、也没有在成为提供者前接受临床创伤个案训练的人。这个定义不是“没有训练”：纳入项目仍包含心理社会干预、研究培训或督导。读者需分清职业身份、训练程度和实际方案，不能把结果缩写成任何志愿者都能提供治疗。"],["综述把很多不同场景放在一起","45 项随机试验、9,431 位战争或人际暴力幸存者，覆盖难民、社区和其他服务环境。干预和对照从支持性照护到不同心理治疗不等，提供者背景也不同。综述在治疗结束时分别合并 PTSD、抑郁、焦虑与功能结局，并探索场景和提供者特征是否解释结果差异。"],["森林图为什么不只看最下面的菱形？","菱形汇总每个结局的平均效应；每个研究的点估计与横线显示单项证据有多大差异及精确度。若研究间方向和幅度差异大，平均效应虽然偏向干预，仍可能不适用于某个具体国家或暴力类型。调节分析是跨研究比较，不等于随机分配某种提供者，所以只能提出解释线索。"],["研究者也指出了参与和证据代表性的问题","作者报告所有结局的平均结果方向有利，同时承认研究间异质性和偏倚风险偏高；结局主要观察到治疗结束时，不能保证长期维持。论文项目中没有亲历暴力者参与研究设计这一限制，提醒我们疗效之外还要问安全、文化适配、权力关系和服务接受度。"],["如何理解四个森林图的效应量","每张森林图都以标准化平均差表示干预与对照的平均差异，负值代表症状或功能损害朝有利方向变化。点估计展示单项研究结果，横线是不确定范围，底部菱形是合并估计。若不同研究的横线重叠少、结果分散，平均值不代表每个场景都会得到同样获益；异质性统计与预测区间能进一步提示新场景可能出现多大差别。"],["为何还要看提供者、场景和干预目标的分析","作者按提供者是否为同伴、场景属于社区或服务机构、干预是否聚焦 PTSD 等特征探索效果差异。这些跨研究亚组并没有随机分派提供者身份，样本研究也可能同时在多个方面不同，所以不能把亚组差异解释成“换成某种职业就会更有效”。它们更适合用来提出下一步设计问题，并提醒服务方案需要匹配当地培训、督导和转介资源。"]]},"prenatal-digital-mindfulness":{"title":"再沿着论文往里读一步","sections":[["研究对象不是所有孕妇","试验纳入 160 名孕妇，主要关注孕期失眠症状，并采用明确的筛选条件；有近期重性抑郁发作、需要其他精神科治疗或某些睡眠问题者会被排除。这样能减少混杂、聚焦课程目标，却意味着发现不一定适用于高危妊娠、复杂共病或没有智能设备的人。"],["六周小程序课程具体做了什么？","Mom Sleep Well 微信小程序提供一组按周编排的数字正念材料和练习，参与者同时处于标准照护之中。论文表格列出模块，截图展示实际界面；这比笼统写“手机正念”更重要，因为课程内容、练习频率、提醒方式和依从程度决定干预究竟是什么。"],["孕期改善与产后维持是两个结论","研究用失眠严重度指数等自评量表在基线、课程结束和约产后 42 天重复测量。模型利用不同时间点可用资料估计平均变化；一次没有完成问卷不等同退出研究。孕期两组的症状差异约两分，产后组间差异不再显著，提示短期效果未显示清楚延续。"],["中介图给出机制假设，不是机制判决","作者检查睡眠担忧、入睡前唤醒和睡眠相关行为是否可能解释症状变化。中介分析会把治疗分组、候选过程变化和失眠分数连起来；时间顺序、未测混杂和自评误差都可能影响路径估计。它能帮助下一项研究选测量指标，却不能单独证明正念通过某一心理机制导致改善。"],["问卷时间点和产后数字为何重要","基线、课程结束和产后随访构成一条短时间线。失眠严重度指数的组间均值变化回答整体症状是否不同，睡眠日记或其他睡眠质量指标则从不同角度补充。产后42天的估计区间更宽、统计上未显示清楚组间差异，所以不能只把孕期两分的改善延长成“疗效持续到产后”。具体随访时点也决定结论的时间范围。"],["数字干预的完成程度是课程剂量的一部分","线上课程并不会因为放在手机里就自动完成。阅读模块数、练习次数、提醒和问卷提交等依从指标能帮助理解参与者实际收到多少干预；但愿意完成练习的人可能本来就有更多时间或动力。随机分组结果反映的是提供课程的整体效果，按完成程度拆分的关联则更容易受到自我选择影响，不能当作随机比较。"]]},"digital-behavioural-activation":{"title":"再沿着论文往里读一步","sections":[["行为激活的核心不是“多做点事”","这类治疗帮助患者重新安排有意义或带来掌控感的活动，观察活动、情绪和回避之间的联系。搬到数字平台后，课程可能是自助模块、短信提示、远程带领或混合支持。综述首先要区分这些具体做法，否则同一个“数字行为激活”标签会把完全不同的服务压成一类。"],["筛选流程和干预特征表值得先看","作者纳入 18 篇论文、17 项随机试验；PRISMA 图展示记录如何逐步筛选，研究特征和干预特征表则说明受试者、平台、支持方式和比较组。试验里某种方法有效，不等于市场上任意一款应用都复现了同一干预成分。"],["为什么森林图按随访月份拆开？","抑郁症状在两、三、六个月出现改善信号，十二个月的估计不再显著；行为激活程度、生活质量和压力又有各自不同的数据量与时间轨迹。每个结局的参与者和试验可能不同，因此不能把不同面板读成同一批人的连续变化，也不能用短期显著替代长期维持。"],["统计合并不能消除发表和实施问题","研究间平台、指导剂量、常规照护内容和结局测量各异，偏倚风险图提醒读者结果可能受到研究设计影响。综述对总体有效性的估计，不能直接告诉服务机构成本、用户留存、危机处理和隐私保护是否合格。下一步不仅要重复平均效果，也要记录谁完成课程、谁中途退出、哪些人更需要人工支持。"],["把依从和退出放进效果解释","系统综述会尽量按随机分组分析，但原始试验报告的退出、课程完成和失访程度不一。若症状更重的人更难完成线上课程，完成者分析可能夸大对所有人的可行性；若对照组同样得到其他服务，组间差异也会变小。读每个随访时间的合并效应时，需一起看参与人数、对照类型和偏倚风险，而不是只看一颗菱形。"],["实际部署要补上论文没有汇总的质量问题","疗效综述通常不会统一比较产品如何保护数据、危机时是否有人响应、无障碍程度和长期维护成本。数字项目可能快速扩展，也可能因为平台停止更新或缺少人工转介而中断。论文支持数字行为激活值得继续评估，但实施决策应检查具体产品是否保留了被研究的治疗成分、适用于目标人群并有清楚的风险处理流程。"]]},"digital-eight-disorders":{"title":"再沿着论文往里读一步","sections":[["八个诊断不是同一个治疗目标","研究纳入八类已确诊成人的数字干预试验；失眠课程可能训练睡眠节律，抑郁项目安排活动，强迫或 PTSD 项目则有不同练习与风险要求。跨诊断分析能统一研究框架，却必须保留每类的分层结果，不把交付方式相同误当成疗法相同。"],["168 项研究的平均效应从哪里来？","研究团队使用 Metapsy 数据库，纳入 168 项研究、22,144 人，并采用多层荟萃方法处理同一研究里多个结局。主要合并比较很多来自等待名单等非活性对照；这回答“相对没有同等干预怎样”，不等于“优于日常照护或现有治疗”。对照的强弱会改变效应大小。"],["敏感性分析会让漂亮的总体图变复杂","作者另看低偏倚风险研究、常规照护对照和是否有治疗师指导等条件。低偏倚证据下，能确认的正向结果只剩部分诊断；与常规照护比较时，显著优势也集中在少数病种。研究层面的指导差异不能自动变成某位患者是否需要指导的个人规则。"],["证据确定性、退出和代表性也是结果","作者按病种评估 GRADE 确定性，许多结论被评为低或极低；干预组退出率也常高于对照。现有研究没有完整回答长期效果、产品版本变化、不同国家资源条件和无指导项目的安全管理。地图最有用的地方是看见研究密集区和空白，不是创造一个数字治疗排行榜。"],["多层荟萃分析为何要处理同一研究的多个结果","一项试验可能同时报告多个量表或多个时间点，这些效应并非彼此独立。多层模型允许研究内部结果相关，同时合并不同研究，避免把同一批参与者重复当成完全独立证据。读森林图与总体估计时，统计模型处理了依赖结构，但不会消除原始研究偏倚，也不会让不同诊断、课程与对照突然变得相同。"],["等待名单对照与常规照护对照的含义不同","等待名单组通常暂时没有接受同等强度的新治疗，常规照护组则继续既有服务；数字干预与前者相比，期待、关注和额外接触都可能使效应看起来更大。论文分别检查活性对照、治疗师指导和低偏倚研究，正是为了看总体优势在更严格比较下是否仍存在。临床上不能拿等待名单对照的效果量直接预测优于成熟治疗的幅度。"]]},"cbt-sleep-psychosis":{"title":"再沿着论文往里读一步","sections":[["作者为什么把非随机研究也纳进来？","针对精神病患者睡眠问题的随机试验数量有限，因此系统综述还纳入非随机、前后比较和质性研究，以同时了解效果、体验和适配方式。这样资料更完整，但研究设计证据等级不一；不能把所有研究的效应值当成同一强度。"],["标准 CBT-I 哪些部分可能要调整？","治疗可能涉及睡眠教育、刺激控制、睡眠限制、认知策略和日间活动。表格列出一些研究如何处理害怕上床、幻觉妄想相关担忧、过度睡眠或噩梦，也显示部分研究保留原方案。差异反映临床团队对认知负担、症状稳定和患者偏好的适配，不是一份已统一验证的标准手册。"],["正值、负值和无对照数据的读法","作者把效果方向统一为正值表示睡眠改善；受控研究报告两组之间 Cohen’s d，无对照研究则只是治疗前后变化。置信区间跨零时，结果仍可能与无差异相容。表格按偏倚风险组织，解释效果前应先看设计和风险，而不是挑最大数字。"],["患者体验和安全不能被效应量遮住","质性研究报告治疗是否容易参与、哪些内容有帮助，另外的表格呈现退出和不良事件。症状改善但课程无法坚持，或方案让患者感到不安全，都影响真实服务价值。14 项研究提供了初步线索，不足以确定哪种改编最适合所有人，也不能把 CBT-I 效果直接等同于精神病症状治疗。"],["标准化效应量与前后变化要分清","受控研究的 Cohen’s d 比较干预组与对照组的差异；无对照前后研究只显示治疗后相较治疗前发生变化。后者无法排除自然病程、回归均值或同期服务的影响。综述把不同设计分开整理，是为了让读者不会把“患者睡眠比之前好”误当成“治疗比对照更有效”。解释效应大小时还要检查置信区间、样本数和偏倚风险。"],["什么叫适配，不能只看治疗名称","对精神病患者的 CBT-I 可能需要调整练习速度、睡眠限制幅度、对幻觉或噩梦的讨论方式，以及如何与药物和日间嗜睡管理配合。不同试验把改编写得详细程度不一，因此表格里的适配项目有时只是“研究这样做了”，并不等于经过比较证明更优。未来试验需把组件和决策规则明确记录，才能知道哪些调整帮助参与、哪些影响疗效。"]]},"ceta-ipv-hiv":{"title":"再沿着论文往里读一步","sections":[["研究围绕的是三种压力交会的人群","参与者是在南非约翰内斯堡接受 HIV 抗逆转录病毒治疗、遇到依从困难并有亲密伴侣暴力经历的女性。这个组合让心理健康问题和医疗连续性、安全处境彼此交织。研究结论针对这类服务情境，不代表所有 HIV 感染者或所有暴力经历者都与样本相同。"],["CETA 是怎样放进社区服务的？","共同要素治疗把多种心理治疗中常见的模块按个人问题组合，由受训非专科人员在社区提供。试验还设主动对照、开展安全检查和追踪，并随访至 12 个月。理解比较组实际获得什么很重要：结果是两种服务安排的相对差异，不是 CETA 对“完全没有帮助”的差异。"],["这篇是原试验里的次要心理结局分析","文章聚焦抑郁、PTSD 等心理与行为健康结局；它并不把病毒学控制、药物依从或暴力风险合并成一个总结果。表格分别呈现全体随机样本、完成治疗者和起始症状较高的亚组。全样本最能保留随机比较优势，后两类分析用于补充理解，确定性相对较弱。"],["症状改善不代表安全和医疗需求都解决","12 个月心理症状变化值得关注，但暴力风险、隐私保护、医疗服务连续性和患者自主选择需要单独评估。高基线症状亚组即使显示更大变化，也可能是探索性信号；完成者结果同样可能受到谁能坚持治疗的影响。论文鼓励整合支持，不意味着心理治疗可以替代 HIV 医疗或安全服务。"],["为何全随机样本是最稳的主结果","随机分组后，所有参与者都按原分组纳入分析，能尽量保留起初两组可比性。完成治疗者分析回答“留下并完成的人有什么变化”，但退出本身可能与症状、暴力、安全或医疗压力有关；因此两类人不再天然可比。高基线症状亚组也有相同问题：它可以提出谁可能受益更多的线索，却需要预先指定并有足够样本的独立试验确认。"],["12个月症状量表没有覆盖所有重要结果","抑郁、创伤症状或焦虑量表是研究预设的心理健康结局，但它们不能完整代表安全处境、病毒载量、服药连续性、经济自主和生活质量。原始 CETA 项目还考察医疗相关结果；本篇次要分析的重点更窄。读不同论文时应先确认该文分析哪一组结局，避免把同一试验的心理改善说成所有医疗结果都改善。"]]},"social-determinants-prevention":{"title":"再沿着论文往里读一步","sections":[["“预防”要先说清楚预防什么","综述把心理预防项目和改善社会处境的干预组合起来，纳入 21 个中低收入国家的 31 项随机试验、35,885 人。研究可能测新发抑郁/PTSD，也可能测症状分数；前者是是否达到病例标准，后者是连续变化，两者不能用同一个“风险下降”概括。"],["组合干预里，心理和社会成分都在场","有些项目教应对技能，同时连接经济、教育、家庭或社区资源；对照组可能是常规服务、等待或其他支持。作者把多种组合合并，是为了估算整体策略是否有预防信号，但不同组件的独立作用通常无法从现有研究中拆出来。它不是一套可直接照搬的固定课程。"],["发生率森林图和症状表回答不同问题","PRISMA 流程展示如何从检索走到纳入；森林图以相对风险汇总干预后新发抑郁或 PTSD；时间点表格则把不同随访的症状结果分开。置信区间跨过无效线时，不确定性仍大。焦虑新发缺少可用数据，不能拿抑郁或 PTSD 结果替代。"],["长期结论更窄，社会背景也不一样","较长期的信号主要集中在儿童抑郁症状，而不是所有年龄、所有诊断都持续受益。研究覆盖多个国家与项目，测量和实施差异明显；改善社会决定因素的项目还取决于当地资源是否真实可用。结果支持继续与社区共同设计预防方案，不是证明某项政策或组合已经普遍有效。"],["新发病例的风险比不是症状下降的百分点","森林图中的相对风险把干预组新发病例概率与对照组相比；它不是每个人症状改善百分比，也不能直接读成减少多少个百分点。绝对风险还取决于原本发生率：即使相对风险相同，在不同社区能避免的病例数也会不同。表格把发生率和症状量表分开，正是避免把两类临床问题混为一谈。"],["GRADE 低确定性具体意味着什么","GRADE 会综合偏倚风险、不一致性、间接性、不精确和发表偏倚等因素，判断我们对估计值有多大把握。低或极低确定性不代表干预肯定无效，而是新研究很可能改变目前估计。31 项试验和三万多人听起来庞大，但若各结局能用的研究少、方法有差异或区间很宽，证据确定性仍可能有限。"]]}};
